\label{thm:pack-disk}
  Let $n\in\mathbb{N}$ and $\ell = \left\lceil \sqrt n \right\rceil$. Let $(\mathcal{Z}_t^{\mathrm{disk},n})_{t=0,...,m}$ be a uniform  discrete-time nearest-neighbor walk on $\mathbb{Z}^2$ sampled from $\mathcal{A}_\ell^\mathrm{disk}$ as in~\eqref{eq:Mullin-disk-walk}
  whose law is weighted by $4^{-m}$.   Consider the disk triangulation $T^{\mathrm{disk},n}$ and the   path $\mathfrak{tr}^{\mathrm{disk},n}$ on $\mathcal{F} T^{\mathrm{disk},n}$ given by $\Phi_\mathrm{T}^{\mathrm{disk}}(\mathcal{Z}^{\mathrm{disk},n}) = (T^{\mathrm{disk},n},\mathfrak{tr}^{\mathrm{disk},n}).$ Let $Z^\mathrm{disk}=(L_t^\mathrm{disk},R_t^\mathrm{disk})_{t\in[0,A]}$ be a Brownian motion from~\eqref{eq:variance} conditioned on  $Z_0^\mathrm{disk}=(2,0)$, $Z_A^\mathrm{disk}=(0,0)$ and $Z_t^\mathrm{disk}\in\mathbb{R}_+^2$ with random duration $A$, and let $(\mathbb{D},h^\mathrm{disk},\eta^\mathrm{disk})$ be the clockwise space-filling $\mathrm{SLE}_8$ loop decorated quantum disk generated by $Z^\mathrm{disk}$, embedded such that $\eta^\mathrm{disk}(A/2)=0$.  Then there is a coupling $((\mathcal{Z}^{\mathrm{disk},n})_{n\in\mathbb{N}},Z^\mathrm{disk})$, such that there exists a     circle packing $\mathcal{P}^{\mathrm{disk},n}$ for $T^{\mathrm{disk},n}$ in $\mathbb{D}$ such that as $n\to\infty$, the following holds:
  \begin{enumerate}
      \item the maximal diameter of disks in $\mathcal{P}^{\mathrm{disk},n}$ converges to 0 in probability;
      \item $\sup_{t\in[0,A]}|{n}^{-1/2}\mathcal{Z}_{\lfloor mt/A\rfloor}^{\mathrm{disk},n}-\frac{1}{2}Z_t^\mathrm{disk}|$ converges to 0 in probability; 
      \item  we extend $\mathfrak{tr}^{\mathrm{disk},n}$ as a path    $:[0,m]\to \overline\mathbb{D}$  on embedded faces via linear interpolation, then    $$\sup_{t\in [0,A]}|\eta^\mathrm{disk}(t)-{\mathfrak{tr}}^{\mathrm{disk},n}(mt/A)| \to 0 \text{ in probability as } n\to\infty;$$
      \item let $\mu^{\mathrm{disk},n}$ be the measure on $\mathbb{D}$ that assigns mass $\frac1n$ to the center of  each disk, where  duplication is counted such that $k$ duplicated points have mass $\frac{k}{n}$ in total, and $\nu^{\mathrm{disk},n}$ be the measure on $\partial\mathbb{D}$ that assigns mass $n^{-1/2}$ to each tangent point between a disk in $\mathcal{P}^{\mathrm{disk},n}$ and $\partial\mathbb{D}$. Then the Prokhorov distance between  {$(2\mu^{\mathrm{disk},n},2\nu^{\mathrm{disk},n})$} and $(\mu_{h^\mathrm{disk}},\nu_{h^\mathrm{disk}})$ tends to 0 in probability as $n\to\infty$.
  \end{enumerate}

\label{thm:pack-sph}
    Let $n\in\mathbb{N}$, and $(\mathcal{Z}^{\mathrm{sp},n}_t)_{t=0,...,2n}$ be an element uniformly chosen from $\mathcal{A}_n^\mathrm{sp}$ as in~\eqref{eq:Mullin-sph-walk}. Let $(T^{\mathrm{sp},n},\mathfrak{tr}^{\mathrm{sp},n}) = \Phi_{\mathrm{T}}^\mathrm{sp}(\mathcal{Z}^{\mathrm{sp},n})$ be the sphere triangulation and the path on faces of $T^{\mathrm{sp},n}$. Let $Z^\mathrm{sp}=(L_t^\mathrm{sp},R_t^\mathrm{sp})_{t\in[0,1]}$ be a Brownian motion from~\eqref{eq:variance} conditioned on $Z_0^\mathrm{sp}=Z_1^\mathrm{sp}=(0,0)$ and $Z_t^\mathrm{sp}\in\mathbb{R}_+^2$ for $t\in[0,1]$, and let $(\widehat\mathbb{C},h^\mathrm{sp},\eta^\mathrm{sp})$ be the space-filling $\mathrm{SLE}_8$ curve decorated unit area quantum sphere generated by $Z$, embedded such that $\eta^\mathrm{sp}(0)=\infty,\eta(1/4)=1,\eta(1/2)=0$. Then there is a coupling $((\mathcal{Z}^{\mathrm{sp},n})_{n\in\mathbb{N}},Z^\mathrm{sp})$ and a  circle packing  $\mathcal{P}^{\mathrm{sp},n}$ for $T^{\mathrm{sp},n}$ in $\widehat\mathbb{C}$ such that with probability tending to 1 as $n\to\infty$, $\Phi_{\rm simple}(T^{\mathrm{sp},n})$ is not empty, and under this event, the following holds as $n\to\infty$:
    \begin{enumerate}
        \item  the maximal spherical diameter of disks in $\mathcal{P}^{\mathrm{sp},n}$ tends to 0 in probability;
        \item $\sup_{t\in[0,1]}|(2n)^{-1/2}\mathcal{Z}_{\lfloor 2nt\rfloor}^{\mathrm{sp},n}-\frac{1}{2}Z_t^\mathrm{sp}|$ converges to 0 in probability;
        \item we extend $\mathfrak{tr}^{\mathrm{sp},n}$ as a path $:[0,2n]\to\widehat\mathbb{C}$ on embedded faces via linear interpolation, then 
        $$\sup_{t\in[0,1]}d_{\mathrm{sp}}(\eta^\mathrm{sp}(t),\mathfrak{tr}^{\mathrm{sp},n}(2nt))\to0 \text{ in probability as } n\to\infty;$$
        \item let $\mu^{\mathrm{sp},n}$ be the measure that assigns mass $\frac{1}{n}$ to the center of each disk, with duplication counted. Then the Prokhorov distance between   {$\mu^{\mathrm{sp},n}$} and $\mu_{h^\mathrm{sp}}$ tends to 0 in probability as $n\to\infty$.
    \end{enumerate}

\label{thm:pack-cone}
    Let $(\check{\mathcal{Z}_k^n})_{k\in\mathbb{Z}}$ be the standard nearest-neighbor walks on $\mathbb{Z}^2$, and let $(\mathcal{Z}^n_t)_{t\in\mathbb{R}} = (\check \mathcal{Z}_{\lfloor nt \rfloor}^n)_{t\in\mathbb{R}}$. Let $\Phi_\mathrm{T}(\mathcal{Z}^n) = (T^n,\mathfrak{tr}^n)$ be the triangulation and path on faces of $T^n$ generated through the Mullin bijection. Let $Z=(L_t,R_t)_{t\in\mathbb{R}}$ be the Brownian motion from~\eqref{eq:variance}, and $(\mathbb{C},h,\eta)$ be the space-filling $\mathrm{SLE}_8$ decorated  $\gamma$-quantum cone generated by $Z$ such that $\eta(0)=0$. Then $T^n$ is a.s.\ circle packing parabolic and $\Phi_{\rm simple}(T^n)$ is a.s.\ not empty. Furthermore,  there is a coupling between $(Z,\mathcal{Z}^n)_{n\in\mathbb{N}}$ and circle packings $\mathcal{P}^n$ for $T^n$ in $\mathbb{C}$, such that as $n\to\infty$, the following holds:
    \begin{enumerate}
        \item For every $R>0$, the maximal diameter of disks in $\mathcal{P}^n$ intersecting $B(0;R)$ tends to 0 in probability; \label{result:thm:pack-cone-1}
        \item For every $a>0$, {$\sup_{t\in [-a,a]}|n^{-1/2}\mathcal{Z}^n_t-\frac{1}{2}Z_t|$} converges to 0 in probability; \label{result:thm:pack-cone-2}
        \item If we view $\mathfrak{tr}^n:\mathbb{R}\to\mathbb{C}$ as a path on embedded faces, then for every $a>0$,  {$$\sup_{t\in [-a,a]}|\eta(t)-\mathfrak{tr}^n(t)| \to 0 \text{ in probability;}$$} \label{result:thm:pack-cone-3}
        \item Let $\mu^n$ be the measure that assigns mass $\frac{1}{n}$ to the center of each disk, with duplication counted. Then for each $R>0$, the Prokhorov distance between $2\mu^n|_{B(0;R)}$ and $\mu_h|_{B(0;R)}$ tends to 0 in probability.  \label{result:thm:pack-cone-4}
    \end{enumerate}

\label{thm:unif-disk}
  Let $n\in\mathbb{N}$ and $\ell = \left\lceil \sqrt n \right\rceil$. Let $(\mathcal{Z}_t^{\mathrm{disk},n})_{t=0,...,m}$ and $Z^\mathrm{disk}$ be as in  Theorem~\ref{thm:pack-disk}.   Consider the planar map of disk topology $M^{\mathrm{disk},n}$ and the space-filling path $\mathfrak{tr}^{\mathrm{disk},n}$   encoded by the walk $\mathcal{Z}^{\mathrm{disk},n}$ via the map $\Phi_\mathrm{M}^\mathrm{disk}$ and $\Phi_\mathrm{T}^\mathrm{disk}$, respectively. Let $\mathfrak{M}(M^{\mathrm{disk},n})$ be the Riemann surface associated with the map $M^{\mathrm{disk},n}$. Let $(\mathbb{D},h^\mathrm{disk},\eta^\mathrm{disk})$ be the clockwise space-filling $\mathrm{SLE}_8$ loop decorated quantum disk generated by $Z$, embedded such that $\eta^\mathrm{disk}(A/2)=0$.  Then there is a coupling $((\mathcal{Z}^{\mathrm{disk},n})_{n\in\mathbb{N}},Z)$, such that there exists a  conformal map $\varphi^{\mathrm{disk},n}: \mathfrak{M}(M^{\mathrm{disk},n})\to \mathbb{D}$ such that as $n\to\infty$, the following holds:
  \begin{enumerate}
      \item the maximal diameter of faces under the map $\varphi^{\mathrm{disk},n}$ converges to 0 in probability;
      \item $\sup_{t\in[0,A]}|{n}^{-1/2}\mathcal{Z}_{\lfloor mt/A\rfloor}^{\mathrm{disk},n}-\frac{1}{2}Z_t^\mathrm{disk}|$ converges to 0 in probability; 
      \item if we view $\mathfrak{tr}^{\mathrm{disk},n}:[0,m]\to \overline\mathbb{D}$ as a path on embedded faces, then    $$\sup_{t\in [0,A]}|\eta^\mathrm{disk}(t)-{\mathfrak{tr}}^{\mathrm{disk},n}(mt/A)| \to 0 \text{ in probability as } n\to\infty;$$
      \item let $\mu^{\mathrm{disk},n}$ be the measure on $\mathbb{D}$ that assigns mass $\frac1n$ to the $\varphi^{\mathrm{disk},n}$-image of each vertex,   and $\nu^{\mathrm{disk},n}$ be any measure on $\partial\mathbb{D}$ that assigns mass $n^{-1/2}$ to the $\varphi^{\mathrm{disk},n}$-image of each edge on $\partial (\mathfrak{M}(M^{\mathrm{disk},n}))$. Then the Prokhorov distance between  {$(4\mu^{\mathrm{disk},n},2\nu^{\mathrm{disk},n})$} and $(\mu_{h^\mathrm{disk}},\nu_{h^\mathrm{disk}})$ tends to 0 in probability as $n\to\infty$. The same also holds if   $\mu^{\mathrm{disk},n}$ is any measure on $\mathbb{D}$ that assigns mass $\frac1n$ to the $\varphi^{\mathrm{disk},n}$-image of each face.
  \end{enumerate}

\label{thm:unif-sph}
    Let $n\in\mathbb{N}$, and $(\mathcal{Z}^{\mathrm{sp},n}_t)_{t=0,...,2n}$ and $Z^\mathrm{sp}$ be as in Theorem~\ref{thm:pack-sph}. Let $M^{\mathrm{sp},n}$ and $\mathfrak{tr}^{\mathrm{sp},n}$ be the planar map and space-filling path encoded by the walk $\mathcal{Z}^{\mathrm{sp},n}$ via the map $\Phi_\mathrm{M}^\mathrm{sp}$ and $\Phi_\mathrm{T}^\mathrm{sp}$, respectively. Then with probability tending to 1 as $n\to\infty$, $M^{\mathrm{sp},n}$ has at least 3 vertices. Let $(\widehat\mathbb{C},h^\mathrm{sp},\eta^\mathrm{sp})$ be the space-filling $\mathrm{SLE}_8$ curve decorated unit area quantum sphere generated by $Z^\mathrm{sp}$, embedded such that $\eta^\mathrm{sp}(0)=\infty,\eta(1/4)=1,\eta(1/2)=0$. Then there is a coupling $((\mathcal{Z}^{\mathrm{sp},n})_{n\in\mathbb{N}},Z^\mathrm{sp})$ and a conformal map $\varphi^{\mathrm{sp},n}:\mathfrak{M}(M^{\mathrm{sp},n})\to\widehat\mathbb{C}$ such that the following holds as $n\to\infty$:
    \begin{enumerate}
        \item The maximal spherical diameter of faces under the map $\varphi^{\mathrm{sp},n}$ tends to 0 in probability;
        \item $\sup_{t\in[0,1]}|(2n)^{-1/2}\mathcal{Z}_{\lfloor 2nt\rfloor}^{\mathrm{sp},n}-\frac{1}{2}Z_t^\mathrm{sp}|$ converges to 0 in probability;
        \item If we view $\mathfrak{tr}^{\mathrm{sp},n}:[0,2n]\to\widehat\mathbb{C}$ as a path on embedded faces, then 
        $$\sup_{t\in[0,1]}d_{\mathrm{sp}}(\eta^\mathrm{sp}(t),\mathfrak{tr}^{\mathrm{sp},n}(2nt))\to0 \text{ in probability as } n\to\infty;$$
        \item Let $\mu^{\mathrm{sp},n}$ be the measure that assigns mass $\frac{1}{n}$ to the $\varphi^{\mathrm{sp},n}$ image of each vertex. Then the Prokhorov distance (when viewed under the spherical metric) between  $2\mu^{\mathrm{sp},n}$ and $\mu_{h^\mathrm{sp}}$ tends to 0 in probability as $n\to\infty$. The same also holds if $\mu^{\mathrm{sp},n}$ is any measure on $\widehat\mathbb{C}$ that assigns measure $\frac{1}{n}$ to the $\varphi^{\mathrm{sp},n}$ image of each face.
    \end{enumerate}

\label{thm:unif-cone}

    Let $(\check{\mathcal{Z}_k^n})_{k\in\mathbb{Z}}$ be the standard nearest-neighbor walks on $\mathbb{Z}^2$, and let $(\mathcal{Z}^n_t)_{t\in\mathbb{R}} = (\check \mathcal{Z}_{\lfloor nt \rfloor}^n)_{t\in\mathbb{R}}$.  Let $M^n$ and $\mathfrak{tr}^n$ be the planar map and space-filling path encoded by the walk $\mathcal{Z}^{n}$ via the map $\Phi_\mathrm{M}$ and $\Phi_\mathrm{T}$, respectively. Let $Z=(L_t,R_t)_{t\in\mathbb{R}}$ be a 2D   Brownian motion as in~\eqref{eq:variance}, and $(\mathbb{C},h,\eta)$ be the space-filling $\mathrm{SLE}_8$ decorated  $\gamma$-quantum cone generated by $Z$ such that $\eta(0)=0$. Then  the Riemann surface $\mathfrak{M}(M^n)$ associated with $M^n$ is a.s.\ parabolic. Furthermore,  there is a coupling between $(Z,\mathcal{Z})$ and a conformal map $\varphi^n:M(M^n)\to\mathbb{C}$, such that as $n\to\infty$, the following holds:
    \begin{enumerate}
        \item For every $R>0$, the maximal diameter of faces of $\mathfrak{M}(M^n)$ under the image $\varphi^n$ intersecting $B(0;R)$ tends to 0 in probability; \label{result:thm:unif-cone-1}
        \item For every $a>0$,  {$\sup_{t\in [-a,a]}|n^{-1/2}\mathcal{Z}^n_t-\frac{1}{2}Z_t|$} converges to 0 in probability;\label{result:thm:unif-cone-2}
        \item If we view $\mathfrak{tr}^n:\mathbb{R}\to\mathbb{C}$ as a path on embedded faces, then for every $a>0$,  {$$\sup_{t\in [-a,a]}|\eta(t)-\mathfrak{tr}^n(t)| \to 0 \text{ in probability;}$$} \label{result:thm:unif-cone-3}
        \item Let $\mu^n$ be the measure that assigns mass $\frac{1}{n}$ to the image of each vertex under $\varphi^n$. Then for each $R>0$, the Prokhorov distance between $4\mu^n|_{B(0;R)}$ and $\mu_h|_{B(0;R)}$ tends to 0 in probability. The same applies if $\mu^n$ is any measure that assigns mass $\frac{1}{n}$ to the image of each face under $\varphi^n$. \label{result:thm:unif-cone-4}
    \end{enumerate}

\label{def:cell-config}
    A \textit{cell configuration} on $\mathbb{C}$ consists of the following objects.
    \begin{enumerate}
        \item A locally finite collection $\mathcal{H}$ of  compact connected subsets of $\mathbb{C}$ (``cells") with non-empty interiors whose union is all of $\mathbb{C}$ and such that the intersection of any two elements of $\mathcal{H}$ has zero Lebesgue measure.
        \item A planar map $M$, which we call the \emph{associated map} of $\mathcal{H}$, with vertices $\{v_H:H\in\mathcal{H}\}$. We require that if $v_H$ and $v_{H'}$ are connected by an edge of $M$ then $H\cap H'\neq\emptyset$. 
    \item A function $\mathfrak{c} = \mathfrak{c}_\mathcal{H}$ (``conductance") on the edges  $M$ with values in $(0,\infty)$. 
    \end{enumerate}

\label{def:CellConfigConstraint}
    We define  the following conditions  on the cell configuration $\mathcal{H}$.
    \begin{enumerate}
        \item \textbf{Translation invariance modulo scaling.} There is a (possibly random and $\mathcal{H}$-dependent) increasing sequence of open sets $U_j\subseteq\mathbb{C}$,  each of which is either a square or a disk, whose union is all of $\mathbb{C}$, such that the following is true. Conditional on $\mathcal{H}$ and $U_j$, let $z_j$ for $j\in\mathbb{N}$ be sampled uniformly from Lebesgue measure on $U_j$. Then there exist random numbers $C_j>0$ (possibly depending on $\mathcal{H}$ and $z_j$) such that $C_j(\mathcal{H}-z_j)\to\mathcal{H}$ in law with respect to the metric~\eqref{eq:metric-cc}. \label{cond:def:CellConfigConstraint-1}
        \item  \textbf{Ergodicity modulo scaling.} For every real-valued measurable functions $F=F(\mathcal{H})$ which is invariant under translation and scaling, i.e., $F(C(\mathcal{H}-z)) = F(\mathcal{H})$ for each $z\in\mathbb{C}$ and $C>0$, is a.s.\ equal to a deterministic constant.  \label{cond:def:CellConfigConstraint-2}

        \item \textbf{Rotation invariance in law.} For some $\theta_0\in(0,2\pi)\backslash\{\pi\}$, $e^{i\theta}\mathcal{H}$ has the same law as $\mathcal{H}$.  \label{cond:def:CellConfigConstraint-3}




    \end{enumerate}

\label{def:CellConfigConstraint-large}
    Let $\mathcal{H}$ and $\mathcal{H}^\mathrm{large}$ be cell configurations. We define  the following conditions  on the cell configurations $(\mathcal{H},\mathcal{H}^\mathrm{large})$.
     \begin{enumerate}[(i)]
        \item The cell configuration  $\mathcal{H}^{\rm large}$ is isomorphic to $\mathcal{H}$, in the sense that $\mathcal{H}$ and $\mathcal{H}^{\rm large}$ have isomorphic associated maps; below we let $\phi:\mathcal{H}\to\mathcal{H}^{\rm large}$ denote  {the} isomorphism.   \label{cond:def:CellConfigConstraint-large-(i)}
        \item The convex hull of $H$ is contained in the convex hull of $\phi(H)$  {for any $H\in\mathcal{H}$}. \label{cond:def:CellConfigConstraint-large-(ii)}
        \item Almost surely,  {for each given $\varepsilon>0$, there exists $R>0$ such that for $r>R$ and each horizontal or vertical line segment $\ell\subseteq B(0;r)$ with length at least $\varepsilon r$}, the following holds. For any two different cells $H,H'\in\mathcal{H}$ intersecting $\ell$, $\phi(H),\phi(H')$ also intersect $\ell$, and we can find a path $H\sim H_1\sim\cdots\sim H_k\sim H'$, such that $\phi(H_j)$ intersects $\ell$ for each $j$. \label{cond:def:CellConfigConstraint-large-(iii)}
    \end{enumerate}

\label{thm:CellSystemPack}
    Let $\mathcal{H}$ be a random cell configuration such that its associated map is a simple infinite plane triangulation. Suppose $\mathcal{H}$   satisfies all the conditions in Definition~\ref{def:CellConfigConstraint} and the moment bound
    \begin{equation}\label{eq:thm-inv-circle}
        \mathbb{E}\Big[\frac{\mathrm{diam}(H_0)^2}{\mathrm{area}(H_0)}\deg(H_0)^4\Big]<\infty.
    \end{equation}
    Further assume that there exists another cell configuration $\mathcal{H}^\mathrm{large}$ satisfying the conditions in Definition~\ref{def:CellConfigConstraint} and~\eqref{eq:thm-inv-circle}, and assume that $(\mathcal{H},\mathcal{H}^\mathrm{large})$ satisfies the conditions in Definition~\ref{def:CellConfigConstraint-large}. Then the associated map is a.s.\ circle packing parabolic, and there is a circle packing $\mathcal{P}$ for $\mathcal{H}$ such that  {up to a reflection,} the following is true.
    Almost surely, for any $\varepsilon>0$, there exists $R_0>0$ such that for every $r>R_0$, the maximal diameter of disks in $\mathcal{P}$ intersecting $B(0;r)$ is less than $\varepsilon r$. Furthermore, for $H\in\mathcal{H}$,  letting $o(H)$ be the center of the disk for $H$ in $\mathcal{P}$, almost surely, 
    \begin{equation}\label{eq:thm:CellsystemPack}
        \lim_{r\to\infty}\frac{1}{r}\max_{H\in \mathcal{H}(B(0;r))}|c(H)-o(H)| = 0.
    \end{equation}

\label{thm:invariance-uniformization}
    Let $\mathcal{H}$ be a random cell configuration such that its associated map has  {whole-plane topology}.  Suppose $\mathcal{H}$ satisfies all the conditions in Definition~\ref{def:CellConfigConstraint} and the moment bound
    \begin{equation}\label{eq:thm-inv-circle-1}
        { \mathbb{E}\Big[ \max_{H\in \mathcal{H}^{\mathrm{face}}_0}\Big(\frac{\mathrm{diam}(H)^2}{\mathrm{area}(H)}\big(d_0^f+\deg(H)\big)^6\Big)\Big]<\infty. }
    \end{equation}
      Further assume that there exists another cell configuration $\mathcal{H}^\mathrm{large}$ satisfying the conditions in Definition~\ref{def:CellConfigConstraint} and~\eqref{eq:thm-inv-circle-1}, and assume that $(\mathcal{H},\mathcal{H}^\mathrm{large})$ satisfies the conditions in Definition~\ref{def:CellConfigConstraint-large}. 
    Then the Riemann surface $\mathfrak{M}(\mathcal{H})$ formed by the associated map of $\mathcal{H}$ is a.s.\   parabolic, and there exists a  conformal map $\varphi_0:\mathfrak{M}(\mathcal{H})\to\mathbb{C}$ for $\mathcal{H}$ such that {up to a reflection}, the following is true.  Then {almost surely}, 
    \begin{equation}\label{eq:thm:invariance-uniform}
        \lim_{r\to\infty}\frac{1}{r}\max_{H\in \mathcal{H}(B(0;r))}|c(H)-\varphi_0(v_H)| = 0.
    \end{equation}
    Furthermore,  for each $f\in \mathcal{F}\mathcal{H}$, we write $\mathfrak{f}_{f}$ for the face for $f$ on  $\mathfrak{M}(\mathcal{H})$,  
     \begin{equation}\label{eq:thm:invariance-uniform-1}
        \lim_{r\to\infty}\frac{1}{r}\max_{f\in \mathcal{F}\mathcal{H}(B(0;r))}\mathrm{diam}(\varphi_0(\mathfrak{f}_{f})) = 0,
    \end{equation}
    where $\mathcal{F}\mathcal{H}(B(0;r))$ is the set of faces of the associated map for $\mathcal{H}$ which are incident to cells in $\mathcal{H}(B(0;r))$.  {Finally, for each $\varepsilon>0$, almost surely for sufficiently large $r>0$, if the embedded face $\varphi_0(\mathfrak{f}_{f})$ intersects $B(0;r)$, then $\mathrm{diam}(\varphi_0(\mathfrak{f}_{f}))<\varepsilon r$.}

\label{def:alpha-cone}
  Fix $\gamma\in(0,2)$, $\alpha<Q$ and let $(B_s)_{s\ge0}$ and $(\widetilde{B}_s)_{s\ge0}$ be independent standard one-dimensional Brownian motions. 
  Let 	
			\begin{equation*}
				Y_t=\left\{ \begin{array}{rcl} 
					B_{t}+\alpha t  & \mbox{for} & t\ge 0,\\
					\widetilde{B}_{-t} +\alpha t & \mbox{for} & t<0,
				\end{array} 
				\right.
			\end{equation*}
			conditioned on   $\widetilde{B}_{t} + (Q-\alpha)t>0$ for all $t>0$.  Recall the decomposition in~\eqref{eq:GFF-decompose}. The $\alpha$-quantum cone is the doubly marked quantum surface $(\mathbb{C},h,0,\infty)/\sim_\gamma$, where $h=\psi_1+\psi_2$, and $(\psi_1,\psi_2)$ are independent random generalized functions in $H_1(\mathbb{C})\times H_2(\mathbb{C})$ whose law can be described as follows.  The common value of $\psi_1$ on $\{|z|=e^{-t}\}$ is equal to $Y_t$ for all $t\in\mathbb{R}$, and $\psi_2$ has the same law as $h_{\mathbb{C},2}$ as in~\eqref{eq:GFF-decompose}.

\label{def:1ddyadic}
    Let $\theta$ be uniformly randomly sampled in $[0,1)$. Let $I(0) = [\theta-1,\theta)$. For $k\in\mathbb{N}$, inductively let $I(k)$ be sampled uniformly from the two dyadic parents of $I(k-1)$.  The \emph{1D uniform dyadic system} $\mathfrak{D}$ is defined by the set of all dyadic descendants of $I(k)$  for each $k\in\mathbb{N}$. For $k\in\mathbb{Z}$, we also write  $I(k)$ for the interval in $\mathfrak{D}$  containing 0 of length $2^{k}$.
    We write  $\Omega_\mathfrak{D}$ for the space of all possible realizations of $\mathfrak{D}$. For $s\in\mathbb{R}$, we write $\mathfrak{D}-s$ for the set $\{[a-s,b-s):[a,b)\in \mathfrak{D}\}$.

\label{lem:Rb}
    Let $\gamma\in(0,2)$, $\alpha<Q$ and $(\mathbb{C},h,0,\infty)$ be the embedding of an $\alpha$-quantum cone as in Definition~\ref{def:alpha-cone}. Let $\eta$ be an independent space-filling SLE loop from $\infty$ to $\infty$ parameterized by $\mu_h$.  For $b>0$, let 
    \begin{align}
        &\mathfrak{R}_b = \sup\{r>0:h_r(0)+Q\log r = \frac{1}{\gamma}\log b\}; \label{eq:Rb}
        \\  &h^b(\cdot)=h(\mathfrak{R}_b\cdot)+Q\log \mathfrak{R}_b-\frac{1}{\gamma}\log b, \qquad \eta^b(\cdot) = \mathfrak{R}_b^{-1}\eta(b\cdot). \label{eq:hb-etab}
    \end{align}
   (Note that by definition $\mathfrak{R}_1=1$.)  Then $(h^b,\eta^b)$ has the same law as $(h,\eta)$. Moreover, there is a constant $a = a(\alpha,\gamma)>0$ such that for any $b_2>b_1>0$ and $C>1$, 
     \begin{equation}\label{eq:Rb-bound}
      \mathbb{P}\Big[C^{-1}(\frac{b_2}{b_1})^{\frac{1}{\gamma(Q-\alpha)}}\leq \frac{\mathfrak{R}_{b_2}}{\mathfrak{R}_{b_1}}\leq C(\frac{b_2}{b_1})^{\frac{1}{\gamma(Q-\alpha)}}\Big]\geq 1-3\exp\big(-\frac{a (\log C)^2}{\log(b_2/b_1)+\log C}\big).
  \end{equation}

\label{lem:SLE-contain}
    Let $\delta>0$. There exists $c>0$ depending only on $\delta$ and $\gamma$ such that  
        \begin{align}
            & \mathbb{P}_\mathrm{E} [B(0;{2^{-\delta k}}) \nsubseteq \eta([-1,1])] \lesssim 2^{-ck}; \label{eq:SLE-contain-ball}  \\
            & \mathbb{P}_\mathrm{E} [\eta([-2^{-\delta k},2^{-\delta k}])\nsubseteq B(0;1/2) ]\lesssim 2^{-ck}. \label{eq:SLE-contained-in-ball}
        \end{align}

\label{lem:SLE-contain-1}
    Let $\delta>0$. There exists $c>0$ depending only on $\delta$ and $\gamma$ such that  
        \begin{align}
            & \mathbb{P}_\mathrm{E} [B(0;{2^{(\frac{1}{\gamma Q}-\delta) k}}) \nsubseteq \eta([-2^k,2^k])] \lesssim 2^{-ck}; \label{eq:SLE-contain-ball-1}  \\
            & \mathbb{P}_\mathrm{E} [\eta([-2^{ k},2^{k}])\nsubseteq B(0;{2^{(\frac{1}{\gamma Q}+\delta)k}}) ]\lesssim 2^{-ck}; \label{eq:SLE-contained-in-ball-1} \\
            &  \mathbb{P}_\mathrm{E} [B(0;{2^{-(\frac{1}{\gamma Q}+\delta) k}}) \nsubseteq \eta([-2^{-k},2^{-k}])] \lesssim 2^{-ck}. \label{eq:SLE-contained-in-ball-2} 
        \end{align}

\label{lem:SLE-contain-2}
  Let $\gamma=\sqrt 2$.  There exists $c,c_1>0$ such that
    \begin{equation}
        \mathbb{P}_\mathrm{Q} [\mathbb{D}\nsubseteq \eta([-2^{c_1 k},2^{c_1k}]) ]\lesssim 2^{-ck}.
    \end{equation}

\label{lem:basic-hat}
Let $(\mathcal{Z}_t)_{t\in \mathcal{J}}$ be  a nearest neighbor walk on $\mathbb{Z}^2$ as above. 
    \begin{enumerate}
        \item Suppose $\mathcal{J}=\mathbb{Z}$ and $\mathcal{Z}$ satisfies~\eqref{eq:walk-liminf}. Then   $\Phi_{\rm simple}\circ \Phi_\mathrm{T}(\mathcal{Z})=\Phi_\mathrm{T}\circ\Phi_{\rm simple} (\mathcal{Z})$. Here we  set $\Phi_\mathrm{T}(\mathring \mathcal{Z})=\emptyset$ if $\mathring\mathcal{Z}$ is empty.
        \item  For any $t\in\mathring\mathcal{J}$ and $a>0$, if the times $\inf\{s>t:\mathcal{L}_s-\mathcal{L}_t \leq -a\}$ and $\inf\{s>t:\mathcal{R}_s-\mathcal{R}_t \leq -a\}$ are finite, then they are in $\mathring\mathcal{J}$.
        \item Suppose $t_1<t_2$ are in $\mathring\mathcal{J}$. Then the restriction of the walk $\Phi_{\rm simple}(\mathcal{Z})$ to the interval $\mathring\mathcal{J}\cap[t_1,t_2]$ is equal to $\Phi_{\rm simple}(\mathcal{Z}|_{[t_1,t_2]})$.
    \end{enumerate}

\label{prop:Mullin-sph}
    For any $n\in\mathbb{N}$, the map $\Phi_{\mathrm{M}}^{\rm sp}$ is a bijection between the following sets:
    \begin{itemize}
        \item The set $\mathcal{A}_n^\mathrm{sp}$ of nearest-neighbor walks defined in terms of~\eqref{eq:Mullin-sph-walk}.
        \item The set of tuples $(M,e_0,\mathfrak{T})$, where $(M,e_0)$ is a rooted planar map with $n$ edges and $\mathfrak{T}$ is a spanning tree on $M$.
    \end{itemize}

By the reflection principle, the number of walks $(\mathcal{X}_k)_{k=0,...,2n+\ell-1}$ with jumps $\pm 1$ on $\mathbb{Z}$ such that $\mathcal{X}_0=\ell-1$, $\mathcal{X}_{2n+\ell-1}  = \inf_{0\leq k\leq 2n+\ell}\mathcal{X}_{k}=0$ is $\binom{2n+\ell-1}{n}-\binom{2n+\ell-1}{n-1} = \frac{\ell}{n+\ell}\binom{2n+\ell-1}{n}$. Therefore
    \begin{equation}
    \begin{split}
    \#\mathcal{A}_{\ell,2n+\ell}^\mathrm{disk} &= \sum_{k=0}^{n}\binom{2n+\ell-1}{2k+\ell-1}\frac{\ell}{k+\ell}\binom{2k+\ell-1}{k}\frac{1}{n-k+1}\binom{2n-2k}{n-k} =  \sum_{k=0}^n \frac{\ell\cdot(2n+\ell-1)!}{k!(k+\ell)!(n-k)!(n-k+1)!} 
    \\ &= \binom{2n+\ell-1}{n}\frac{\ell}{(n+1)(n+\ell)}\sum_{k=0}^n\binom{n+\ell}{n-k}\binom{n+1}{k} = \frac{\ell}{(n+1)(n+\ell)}\binom{2n+\ell-1}{n}\binom{2n+\ell+1}{n}.
    \end{split}
    \end{equation}
    The claim for $\#\mathcal{A}_n^\mathrm{sp}$ follows since $\#\mathcal{A}_n^\mathrm{sp} = \#\mathcal{A}_{1,2n+1}^\mathrm{disk}$.

\label{prop:Mullin-bij-disk}
    For any $n\in\mathbb{N}$, the map $\Phi_{\mathrm{M}}^{\rm disk}$ is a bijection between the following sets:
    \begin{itemize}
        \item The set of nearest-neighbor walks $\mathcal{Z} = (\mathcal{Z}_t)_{t=0,...,2n-\ell-2}$ on $\mathbb{Z}^2$ satisfying~\eqref{eq:walk-excursion-disk}.
        \item The set of tuples $(M,e_0,\mathfrak{T})$, where $(M,e_0)$ is a planar map with disk topology of boundary length $\ell+1$   with $n$ edges and $\mathfrak{T}$ is a spanning tree on $M$ with wired boundary condition where all the boundary edges  are on $\mathfrak{T}$.
    \end{itemize}

\label{prop:KMT-gamma-cone}
    Under the probability measure $\mathbb{P}_\mathrm{Q}$, there exists a process $(\mathcal{Z}_t)_{t\in\mathbb{R}} = (\mathcal{L}_t,\mathcal{R}_t)_{t\in\mathbb{R}}$ which is right continuous and has left limit and satisfies the following.
    \begin{enumerate}[(i)]
        \item The law of $(\mathcal{Z}_t)_{t\in\mathbb{R}}\in D(\mathbb{R},\mathbb{R}^2)$ is a continuous-time nearest neighbor walk on $\mathbb{Z}^2$, such that  the set of times $\mathcal{J}$ at which $\mathcal{Z}$ makes a jump is given by a Poisson point process  {on $\mathbb{R}$ with unit rate}, and conditioned on $\mathcal{J}$ the steps of $\mathcal{Z}$ are i.i.d.\ and uniform in $\{(1,0),(0,1),(-1,0),(0,-1)\}$. \label{cond:prop:KMT-gamma-cone-(i)}
        \item For any $C_1>1$, there exists $C'>1$ such that for any $m\in\mathbb{N}$, 
        $$\mathbb{P}_\mathrm{Q}\big[\sup_{t\in I(m)}\|Z_t-\mathcal{Z}_t\|\geq C'm\big]\leq 2^{-C_1m}$$
        where $I(m)$ is the interval in $\mathfrak{D}$ of length $2^m$ containing 0; \label{cond:prop:KMT-gamma-cone-(ii)}
        \item                                                                                                                                                                                             
        There exists a measurable function $g$ such that $\mathcal{Z} = g(h,h^\mathrm{IG}, \mathfrak{U}).$ \label{cond:prop:KMT-gamma-cone-(iii)}
    \end{enumerate}

\label{thm:KMT-0-cone} 
     Under the probability measure $\mathbb{P}_\mathrm{E}$, we have the following.
     \begin{enumerate}[(i)]
         \item Let  { $g$} be the same as in Theorem~\ref{prop:KMT-gamma-cone}, and define $\mathcal{Z}= g(h,h^\mathrm{IG}, \mathfrak{U})$. Then the walk $\mathcal{Z}$          

         is a well-defined continuous time walk in $\mathbb{Z}^2$. The process  $(\mathcal{Z}_t)_{t\in\mathbb{R}}\in D(\mathbb{R},\mathbb{R}^2)$   makes jumps in $\{(0,1),(1,0),(0,-1),(-1,0)\}$, and makes finitely many jumps during any finite time   interval. Furthermore, $g$ is translation invariant modulo scaling, in the sense that for any $z\in\mathbb{C}$ and $C>0$, if we set $\tau_z$ to be the time when the space-filling curve $\eta$ hits $z$, then
         \begin{equation}\label{eq:shift-inv-Z}
             (\mathcal{Z}_{t+\tau_z}-\mathcal{Z}_{\tau_z})_{t\in\mathbb{R}} = g(h(C\cdot+z)+Q\log C, h^{\mathrm{IG}}(C\cdot+z), \mathfrak{U}-\tau_z).
         \end{equation} \label{cond:thm:KMT-0-cone-(i)} 
         \item For any $C_1>1$, there exists $C',C''>1,$ such that for any $m\in\mathbb{N}$, 
        $$ {\mathbb{P}_\mathrm{E}\big[\sup_{t\in [-2^m,2^m]}|Z_t-\mathcal{Z}_t|\geq C'm\big]\leq C''2^{-C_1m};}$$   \label{cond:thm:KMT-0-cone-(ii)} 


        \item Let $G:D(\mathbb{R},\mathbb{R}^2)\times\Omega_\mathfrak{D}\to\{0,1\}$ be a measurable function and let \begin{equation}\label{eq:def-A} A = \{\exists s\in I(0):G(\mathcal{Z}(\cdot +s)-\mathcal{Z}(s),\mathfrak{D}-s)=1\}.\end{equation}
        Suppose $A\in\sigma(\mathcal{Z}|_{I(k)},I(k))$. Then there exists a constant $C_0>1$ such that for all $k\in\mathbb{N}$,
        \begin{equation}\label{eq:KMT-0-cone}
            \mathbb{P}_\mathrm{E}[A] \leq \mathbb{P}_\mathrm{Q}[A]^{1/4}2^{C_0k}+2^{-k/C_0}.
        \end{equation} \label{cond:thm:KMT-0-cone-(iv)} 
     \end{enumerate}

\label{def:walk}
    We call a process $\mathcal{Z}:J\to\mathbb{Z}^2$ a continuous-time nearest neighbor walk on $\mathbb{Z}^2$, if the trajectories $t\mapsto \mathcal{Z}_t$ are right-continuous and with a finite number of jumps in any bounded interval, and the jumps of the process take their values in $\{(-1,0),(0,1),(0,-1),(1,0)\}$. We   define $\Delta\mathcal{Z}_t = \mathcal{Z}_t - \lim\limits_{s\uparrow t}\mathcal{Z}_{s}$. Let $\mathcal{Z} = (\mathcal{L},\mathcal{R}):J\to\mathbb{Z}^2$ be a continuous-time  nearest neighbor walk on $\mathbb{Z}^2$. We further say $\mathcal{Z}$ has \emph{rate $\lambda>0$} if the jump times for $\mathcal{Z}$ is distributed as a Poisson point process with intensity  $\lambda$ times the Lebesgue measure on $J$, {and conditioned on the jump times, the jumps are independent and uniform among the four directions}. Let $\mathcal{J} = \{t\in J:\Delta\mathcal{Z}_t\neq 0\}$ be the set of times when $\mathcal{Z}$ makes a jump,  and let
   \begin{align}
       & \mathcal{J}_{\mathrm{L}} = \{t\in J:   \Delta\mathcal{L}_t  \neq 0\},  \ \ \mathcal{J}^-_{\mathrm{L}} = \{t\in J:   \Delta\mathcal{L}_t  =-1\}, \    \mathcal{J}^-_{\mathrm{R}} = \{t\in J:   \Delta\mathcal{R}_t =-1\}, \    \mathcal{J}^-  = \mathcal{J}^-_\mathrm{L}\cup\mathcal{J}^-_\mathrm{R};\\
       &\mathcal{J}_{\mathrm{R}} = \{t\in J:   \Delta\mathcal{R}_t  \neq 0\},  \ \ \mathcal{J}^+_{\mathrm{L}} = \{t\in J:   \Delta\mathcal{L}_t  =1\}, \    \mathcal{J}^+_{\mathrm{R}} = \{t\in J:   \Delta\mathcal{R}_t =1\}, \      \mathcal{J}^+  = \mathcal{J}^+_\mathrm{L}\cup\mathcal{J}^+_\mathrm{R}.
   \end{align}
 {In the case $J = [a,b]$ is finite, we also include the time $a$ in $\mathcal{J}$.}

\label{lem:sew}
    For   $t\in\mathcal{J}$, let  $v_\mathrm{L}$ and $v_\mathrm{R}$ be the left and right endpoint of the edge $\mathfrak{e}_t$, respectively. Then $v_\mathrm{L} = \mathfrak{v}_{t_\mathrm{L}}$ and $v_{\mathrm{R}} = \mathfrak{v}_{t_\mathrm{R}}$, where
    \begin{equation}\label{eq:lem:sew} t_\mathrm{L} = \inf\{s>t:\mathcal{L}_s = \mathcal{L}_t-1\}, \ \ \ t_\mathrm{R} = \inf\{s>t:\mathcal{R}_s = \mathcal{R}_t-1\}.\end{equation}
    In particular, if $t$ is in $\mathcal{J}^-$ (resp.\ $\mathring\mathcal{J}^-$), then $\{t,t_\mathrm{L}\},\{t,t_\mathrm{R}\}$ are edges in $ \mathcal{E}_\mathrm{T}$ (resp.\ $ \mathring\mathcal{E}_\mathrm{T}$).
   Furthermore, for $t\in\mathcal{J}^+_\mathrm{L}$, let $v_{\mathrm{L},2}$ be the vertex in the triangle $\mathfrak{tr}(t)$ that is not on the edge $\mathfrak{e}_t$. Then $v_{\mathrm{L},2} = \mathfrak{v}_{t_{\mathrm{L},2}}$ where \begin{equation}\label{eq:lem:sew-1} t_{\mathrm{L},2} = \inf\{s>t:\mathcal{L}_s = \mathcal{L}_t-2\}, \ \ \  t_{\mathrm{R},2} = \inf\{s>t:\mathcal{R}_s = \mathcal{R}_t-2\}.\end{equation} The same statement holds for $t\in\mathcal{J}^+_\mathrm{R}$ and $(\mathcal{L},\mathrm{L})$ replaced by $(\mathcal{R},\mathrm{R})$.

\label{prop:time-set-A-0}
 There exists a.s.\ finite subsets $(\mathcal{T}_{s}^{\mathrm{C},{d}})_{s\in\mathcal{J}^-}$   of $\mathcal{J}^-$ such that the following is true. For each $s_0,u_0\in \mathcal{J}^-$, we have:
    \begin{enumerate}
        \item $s_0\in \mathcal{T}_{s_0}^{\mathrm{C},{d}}$.\label{cond:prop:time-set-A-0-1}
        \item $s_0\in \mathcal{T}_{u_0}^{\mathrm{C},d}$ if and only if $u_0\in \mathcal{T}_{s_0}^{\mathrm{C},d}$.\label{cond:prop:time-set-A-0-2}
        \item If $\{s_0,u_0\}\in \mathcal{E}_{\rm{T}}$ then $u_0\in \mathcal{T}_{s_0}^{\mathrm{C},d}$.\label{cond:prop:time-set-A-0-3}
        \item The set $\mathcal{T}_{s_0}^{\mathrm{C},d}$ is $\mathrm{G}$-connected.  \label{cond:prop:time-set-A-0-4}
        \item Let $k,d\in\mathbb{N}$ and $\delta\in(0,1)$. There exists some constant $c$ depending on $d$ and $\delta$ such that 
        $$\mathbb{P}_\mathrm{E}[\bigcup_{t\in I((1-\delta)k)} \mathcal{T}_t^{\mathrm C,d}\nsubseteq I(k)]\lesssim 2^{-ck}.$$ \label{cond:prop:time-set-A-0-5}
        \item  For each $d\in\mathbb{N}$, there exists some constant $c$ depending only on $d$ such that for large enough $k$, 
      \begin{equation}\mathbb{P}_\mathrm{E}\big[\exists t\in [-2^{k+1},2^{k+1}]\cap \mathcal{J}^-: \#\mathcal{T}_t^{\mathrm{C},d}>k^{27} \big]\lesssim 2^{-ck}.\end{equation} \label{cond:prop:time-set-A-0-6}
      \item  {Fix $d\geq 3$. Let $s,s'\in \mathcal{J}^-_\mathrm{L}$ such that $\{s,s'\}\in \mathcal{E}_\mathrm{G}$ or $s'\in \mathcal{T}_s^{\mathrm{C},1}$. Then there exists $t_0,...,t_n\in \mathcal{T}_{s}^{\mathrm{C},d}$ such that $t_0=s$, $t_n=s'$ and for each $j=0,...,n-1$, $\{t_j,t_{j+1}\}\in\mathcal{E}_\mathrm{T}$.} \label{cond:prop:time-set-A-0-7}
    \end{enumerate}

\label{prop:time-set-A}
  There exists a.s.\ finite subsets $(\mathring\mathcal{T}_{s}^{\mathrm{C},{d}})_{s\in\mathring\mathcal{J}^-}$ of $\mathring\mathcal{J}^-$ such that the following is true. For each $s_0,u_0\in\mathring\mathcal{J}^-$, we have:
    \begin{enumerate}
        \item $s_0\in \mathring\mathcal{T}_{s_0}^{\mathrm{C},{d}}$.\label{cond:prop:time-set-A-1}
        \item $s_0\in \mathring\mathcal{T}_{u_0}^{\mathrm{C},d}$ if and only if $u_0\in \mathring\mathcal{T}_{s_0}^{\mathrm{C},d}$.\label{cond:prop:time-set-A-2}
        \item If $\{s_0,u_0\}\in \mathring\mathcal{E}_{\rm{T}}$ then $u_0\in \mathring\mathcal{T}_{s_0}^{\mathrm{C},d}$.\label{cond:prop:time-set-A-3}
        \item  $\mathring\mathcal{T}_{s_0}^{\mathrm{C},d}$ is $\mathrm{G}$-connected.  \label{cond:prop:time-set-A-4}
        \item Let $k,d\in\mathbb{N}$ and $\delta\in(0,1)$. There exists some constant $c$ depending on $d$ and $\delta$ such that 
        $$\mathbb{P}_\mathrm{E}[\bigcup_{t\in I((1-\delta)k)} \mathring\mathcal{T}_t^{\mathrm C,d}\nsubseteq I(k)]\lesssim 2^{-ck}.$$ \label{cond:prop:time-set-A-5}
        \item  For each $d\in\mathbb{N}$, there exists some constant $c$ depending only on $d$ such that for large enough $k$, 
      \begin{equation}\label{eq:cond:prop:time-set-A-6}\mathbb{P}_\mathrm{E}\big[\exists t\in [-2^{k+1},2^{k+1}]\cap \mathring\mathcal{J}^-: \#\mathring\mathcal{T}_t^{\mathrm{C},d}>k^{27} \big]\lesssim 2^{-ck}.\end{equation} \label{cond:prop:time-set-A-6}
       \item  {Fix $d\geq 3$. Let $s,s'\in\mathring\mathcal{J}^-$ such that  $\{s,s'\}\in \mathring\mathcal{E}_\mathrm{G}$ or $s'\in  \mathring\mathcal{T}_{s}^{\mathrm{C},{1}}$. Then there exists $t_0,...,t_n\in \mathring\mathcal{T}_{s}^{\mathrm{C},d}$ such that $t_0=s$, $t_n=s'$ and for each $j=0,...,n-1$, $\{t_j,t_{j+1}\}\in\mathring\mathcal{E}_\mathrm{T}$.} \label{cond:prop:time-set-A-7}
    \end{enumerate}

\label{lem:def-wh-T-Cd}
    For each $s_0,u_0\in\mathring\mathcal{J}^-$, the following hold.
    \begin{enumerate}
        \item $s_0\in \mathring\mathcal{T}_{s_0}^{\mathrm{C},{d}}$. \label{cond:lem:def-wh-T-Cd-1}
        \item $s_0\in \mathring\mathcal{T}_{u_0}^{\mathrm{C},d}$ if and only if $u_0\in \mathring\mathcal{T}_{s_0}^{\mathrm{C},d}$. \label{cond:lem:def-wh-T-Cd-2}
        \item If $\{s_0,u_0\}\in \mathring\mathcal{E}_{\rm{T}}$ then $u_0\in \mathring\mathcal{T}_{s_0}^{\mathrm{C},d}$. \label{cond:lem:def-wh-T-Cd-3}
        \item  $\mathring\mathcal{T}_{s_0}^{\mathrm{C},d}$ is $\mathrm{G}$-connected. \label{cond:lem:def-wh-T-Cd-4} 
    \end{enumerate}

\label{lem:def-wh-T-Dd}
    For each $s_0,u_0\in\mathring\mathcal{J}^-$, the following hold.
    \begin{enumerate}
        \item $s_0\in \mathring\mathcal{T}_{s_0}^{\mathrm{D},{d}}$. \label{cond:lem:def-wh-T-Dd-1}
        \item $s_0\in \mathring\mathcal{T}_{u_0}^{\mathrm{D},d}$ if and only if $u_0\in \mathring\mathcal{T}_{s_0}^{\mathrm{D},d}$. \label{cond:lem:def-wh-T-Dd-2}
        \item  {For $d\geq 2$}, if $\{s_0,u_0\}\in \mathring\mathcal{E}_{\rm{G}}$ then $u_0\in \mathring\mathcal{T}_{s_0}^{\mathrm{D},d}$. \label{cond:lem:def-wh-T-Dd-3}

        \item $\mathring\mathcal{T}_{s_0}^{\mathrm{C},d}\subseteq \mathring\mathcal{T}_{s_0}^{\mathrm{D}, d+1}$ and $\mathring\mathcal{T}_{s_0}^{\mathrm{D},d}\subseteq \mathring\mathcal{T}_{s_0}^{\mathrm{C}, d+1}$. \label{cond:lem:def-wh-T-Dd-4}
        \item  $\mathring\mathcal{T}_{s_0}^{\mathrm{D},{d}}$ is $\mathrm{T}$-connected. \label{cond:lem:def-wh-T-Dd-5}
    \end{enumerate}

Assertion~\ref{cond:lem:def-wh-T-Dd-1} and Assertion~\ref{cond:lem:def-wh-T-Dd-2} are clear from the definition~\eqref{eq:def-wh-TtDd}.

      To prove Assertion~\ref{cond:lem:def-wh-T-Dd-3}, without loss of generality assume $s_0<u_0$. If $\mathring I_{u_0} = [s_0,u_0]$, then $\mathring\tau_{s_0,\mathrm{L}}^{\mathrm{D},d}\geq u_0$ and $u_0\in \mathring\mathcal{T}_{s_0,\mathrm{L}}^{\mathrm{D},d}\subseteq\mathring\mathcal{T}_{s_0}^{\mathrm{D},d}$ since $s_0\in\mathring I_{u_0}$.  Therefore it  suffices to work on the case when $\mathring I_{u_0}$  and $\mathring I_{s_0}$ are disjoint. Without loss of generality assume that condition~(\ref{cond:def-cG-(i)-1}) in the definition of $\mathring\mathcal{E}_\mathrm{G}$ holds; the case where condition~(\ref{cond:def-cG-(ii)-1}) holds follows from a symmetric argument. Then  there are $\widetilde s\in \mathring I_{s_0}$ and $\widetilde u\in \mathring I_{u_0}$ such that~\eqref{eq:def-G-connected-1-1} holds.  Let $\underline{s} = \sup(\mathcal{J}\cap(-\infty,\widetilde s])$. Then by definition of $\mathcal{J}$, $\mathcal{L}_{\widetilde s}=\mathcal{L}_{\underline{s}}$. We claim that $s_0,u_0\in\mathring\mathcal{T}_{\underline{s},\mathrm{L}}^{\mathrm{D},d}$. For $t\in (\underline{s}, \widetilde s]$, $\mathcal{L}_t=\mathcal{L}_{\underline{s}}$, and for every $t\in (\widetilde s,\widetilde u]$, 
    \begin{equation*}
        \begin{split}
            \mathcal{L}_t-\mathcal{L}_{\underline{s}}&=\mathcal{L}_t-\mathcal{L}_{\widetilde s}\geq L_t-L_{\widetilde s} - \sup_{t'\in [\widetilde s,t]}|(\mathcal{L}_{t'}-\mathcal{L}_{\widetilde s})-(L_{t'}-L_{\widetilde s})|\\
            &\geq - \sup_{t'\in [\widetilde s,t]}\big(|(\mathcal{L}_{t'}-\mathcal{L}_{\underline s})-(L_{t'}-L_{\underline s})|+|(\mathcal{L}_{\widetilde s}-\mathcal{L}_{\underline s})-(L_{\widetilde s}-L_{\underline s})|\big)\\
            &> -2\sup_{t'\in [\underline s,t]}|(\mathcal{L}_{t'}-\mathcal{L}_{\underline s})-(L_{t'}-L_{\underline s})|\geq  -2\mathring\Delta_{\mathrm{L}}[\underline{s},t]+2,
        \end{split}
    \end{equation*}
    where in the second line we used $L_t\geq L_{\widetilde s}$ on $[\widetilde s,\widetilde u]$ and a triangle inequality and in the last line we used the definition~\eqref{eq:def-delta-mr-tTDd}.  By   definition~\eqref{eq:def:mr-tau-TtDd}, this further implies $\mathring\tau_{\underline{s},\mathrm{L}}^{\mathrm{D},d}\geq\widetilde u$ and therefore $\mathring\tau_{\underline{s},\mathrm{L}}^{\mathrm{D},d}\geq u_0$. Since $\underline{s}\in \mathring I_{s_0}$, we have $s_0\in \mathring\mathcal{T}_{\underline{s}, \mathrm{L}}^{\mathrm{D},d}$. Now using $L_{\widetilde u}=L_{\widetilde s}$, by a triangle inequality,
     \begin{equation}\label{eq:pf-def-T-Dd-1}
        \begin{split}
            |\mathcal{L}_{\widetilde u}-\mathcal{L}_{\underline{s}}|&=|\mathcal{L}_{\widetilde u}-\mathcal{L}_{\widetilde s}|\leq |L_{\widetilde u}-L_{\widetilde s}| + |(\mathcal{L}_{\widetilde u}-\mathcal{L}_{\widetilde s})-(L_{\widetilde u}-L_{\widetilde s})|\\
            &\leq  |(\mathcal{L}_{\widetilde u}-\mathcal{L}_{\underline s})-(L_{\widetilde u}-L_{\underline s})|+|(\mathcal{L}_{\widetilde s}-\mathcal{L}_{\underline s})-(L_{\widetilde s}-L_{\underline s})|\\
            &\leq 2\sup_{t'\in [\underline s,t]}|(\mathcal{L}_{t'}-\mathcal{L}_{\underline s})-(L_{t'}-L_{\underline s})|\leq 2\mathring\Delta_\mathrm{L}[\underline{s},t].
        \end{split}
    \end{equation}
    Combined with $\mathring\tau_{\underline{s},\mathrm{L}}^{\mathrm{D},d}\geq \widetilde u$, the right hand side of~\eqref{eq:pf-def-T-Dd-1} is less or equal to $\mathring\Delta_{\underline{s},\mathrm{L}}^{\mathrm{D},d}$, which further implies $u_0\in \mathring\mathcal{T}_{\underline{s},\mathrm{L}}^{\mathrm{D},d}$. By~\eqref{eq:def-wh-TtDd}  this implies $u_0\in\mathring\mathcal{T}_{s_0}^{\mathrm{D},d}$, which finishes the proof for Assertion~\ref{cond:lem:def-wh-T-Dd-3}.

     To prove Assertion~\ref{cond:lem:def-wh-T-Dd-4}, we note that for any $t_0\in\mathcal{J}$, $u_0\in [t_0,\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{C},d})\cap \mathring\mathcal{J}^-$ and $t\in [t_0,u_0]$, using the definition of $\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{C},d}$ as in~\eqref{eq:def-delta-mr-tTDd-1},
     \begin{equation*}
     \begin{split}
    \mathcal{L}_t-\mathcal{L}_{t_0} &\geq L_t-L_{t_0} - \sup_{s\in [t_0,t]}|(L_t-\mathcal{L}_t)-(L_{t_0}-\mathcal{L}_{t_0})|\\&\geq -d\cdot\mathring\Delta_{ \mathrm{L}}[t_0,u_0]- \sup_{s\in [t_0,t]}|(L_t-\mathcal{L}_t)-(L_{t_0}-\mathcal{L}_{t_0})|\geq -(d+1)\cdot \mathring\Delta_\mathrm{L}[t_0,u_0] .\end{split}\end{equation*}
    This implies $\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{D},d+1}\geq\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{C},d}$, and in particular $$\mathring\Delta_{t_0,\mathrm{L}}^{\mathrm{D},d+1}\geq \mathring\Delta_{t_0,\mathrm{L}}^{\mathrm{C},d}+\sup_{s\in [t_0,\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{C},d}]}|(L_t-\mathcal{L}_t)-(L_{t_0}-\mathcal{L}_{t_0})|+\mathring N_\mathrm{L}[t_0,\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{C},d}]+1.$$
      Suppose $t\in \mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{C},d}$. Then one can find $t'\in \mathring I_t\cap [t_0,\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{C},d}]$ such that $|L_{t'}-L_{t_0}|\leq \mathring\Delta_{t_0,\mathrm{L}}^{\mathrm{C},d}$, and
     $$|\mathcal{L}_{t'}-\mathcal{L}_{t_0}|\leq |L_{t'}-L_{t_0}|+\sup_{s\in [t_0,\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{C},d}]}|(L_{t'}-\mathcal{L}_{t'})-(L_{t_0}-\mathcal{L}_{t_0})|\leq\mathring \Delta_{t_0,\mathrm{L}}^{\mathrm{D},d+1}.$$
This further implies $\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{C},d}\subseteq \mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d+1}\subseteq \widehat{\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d+1}}$ for any $t_0\in\mathcal{J}$. Similarly $\mathring\mathcal{T}_{t_0,\mathrm{R}}^{\mathrm{C},d}\subseteq \mathring\mathcal{T}_{t_0,\mathrm{R}}^{\mathrm{D},d+1}\subseteq \widehat{\mathring\mathcal{T}_{t_0,\mathrm{R}}^{\mathrm{D},d+1}}$ and further implies the first part of Assertion~\ref{cond:lem:def-wh-T-Cd-4}.

    By a symmetric argument,  $\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{C},d+1}\geq\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{D},d}$, and   \begin{equation}\label{eq:pf-38712387231} \mathring\Delta_{t_0,\mathrm{L}}^{\mathrm{C},d+1}\geq \mathring\Delta_{t_0,\mathrm{L}}^{\mathrm{D},d}+\sup_{s\in [t_0,\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{D},d}]}|(L_t-\mathcal{L}_t)-(L_{t_0}-\mathcal{L}_{t_0})|+\mathring N_\mathrm{L}[t_0,\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{D},d}]+1,\end{equation}
    and also $\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}\subseteq \mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{C},d+1}$.
It remains to take care of $t\in \widehat{\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}}\backslash \mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}$. If this set is not empty, then we must have $[t_0,\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{D},d})\cap \mathring\mathcal{J}^-\neq\emptyset$, otherwise $\widehat{\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}}= \mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d} = \{\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{D},d}\}$. Then by Lemma~\ref{lem:lower-bd-tau-hat-AA}, $\mathcal{L}_s\geq \mathcal{L}_{t_0}-\mathring \Delta_{t_0,\mathrm{L}}^{\mathrm{D},d}-1$ for all $s\in [t_0,\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{D},d}]$. 
Furthermore, there exists $t''\in \mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}$ such that $t = u^{t''}_j$ for some $j$ as in the definition of $\widehat{\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}}$. In particular, $\mathcal{L}_{t''}\geq\mathcal{L}_t$ and further $t'\in \mathring I_{t''}  \cap [t_0,\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{D},d}]$ such that $|\mathcal{L}_{t'}-\mathcal{L}_{t_0}|\leq \mathring\Delta_{t_0,\mathrm{L}}^{\mathrm{D},d}$. Let $t''' = \inf((\mathring\mathcal{J}\cap [t',\infty))\leq t''$. Then by Lemma~\ref{lem:hat-minus}, $\mathcal{L}_{t'}\geq \mathcal{L}_{t'''}-1$ and $\mathcal{L}_{t''}\leq\mathcal{L}_{t'''}+\mathring N_\mathrm{L}[t',t'']$, which further implies that \begin{equation}\label{eq:TtDdcontainedTtCd+1-pf-1} \mathcal{L}_{t_0}-\mathring\Delta_{t_0,\mathrm{L}}^{\mathrm{D},d}-1\leq \mathcal{L}_t\leq \mathcal{L}_{t_0}+\mathring\Delta_{t_0,\mathrm{L}}^{\mathrm{D},d}+ \mathring N_\mathrm{L}[t_0, \mathring\tau_{t_0,\mathrm{L}}^{\mathrm{D},d}]+1.\end{equation} Therefore combined with~\eqref{eq:pf-38712387231}, we have
  $$|L_{t}-L_{t_0}|\leq |\mathcal{L}_{t}-\mathcal{L}_{t_0}|+\sup_{s\in [t_0,\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{D},d}]}|(L_{t'}-\mathcal{L}_{t'})-(L_{t_0}-\mathcal{L}_{t_0})|\leq\mathring \Delta_{t_0,\mathrm{L}}^{\mathrm{C},d+1}.$$
  This verifies that $\widehat{\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}}\subseteq \mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{C},d+1}$, which further implies the second half of Assertion~\ref{cond:lem:def-wh-T-Dd-4}.

 Below we write $\mathring\tau = \mathring\tau_{t_0,\mathrm{L}}^{\mathrm{D},d}$. For Assertion~\ref{cond:lem:def-wh-T-Dd-5}, we first prove that for each $t_0\in\mathcal{J}$, $ \widehat{\mathring\mathcal{T}_{s_0,\mathrm{L}}^{\mathrm{D},d}}$ is $\mathrm{T}$-connected. This is indeed the case where $[t_0,\mathring\tau)\cap \mathring\mathcal{J}^-=\emptyset$, since in this case $ \widehat{\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}} = \{\mathring\tau\}$. Now assume $[t_0,\mathring\tau)\cap \mathring\mathcal{J}^-\neq\emptyset$.  Then  by Lemma~\ref{lem:lower-bd-tau-hat-AA}, $ \mathring\tau \in  \widehat{\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}}$. From our construction of $ \widehat{\mathring\mathcal{T}_{s_0,\mathrm{L}}^{\mathrm{D},d}}$, Lemma~\ref{lem:hat-minus} and Lemma~\ref{lem:lower-bd-tau-hat-AA}, for any $u\in  \widehat{\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}}$ such that $u\neq \mathring\tau$, we have $\mathcal{L}_u>\mathcal{L}_{\mathring\tau}$ and therefore  $u^+:=\inf\{s\geq u:\mathcal{L}_s-\mathcal{L}_u=-1\}\leq\mathring\tau$, $u^+ \in  \widehat{\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}}$ and $\{u,u^+\}\in\mathring\mathcal{E}_\mathrm{T}$ by Lemma~\ref{lem:sew}.  This along with Lemma~\ref{lem:lower-bd-tau-hat-AA} implies that all the elements in $\widehat{\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}}$ are $\mathrm{T}$-connected to $\mathring\tau$ and therefore  $\widehat{\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}}$  is $\mathrm{T}$-connected. Similarly  $\widehat{\mathring\mathcal{T}_{t_0,\mathrm{R}}^{\mathrm{D},d}}$ is $\mathrm{T}$-connected, and  $\widehat{\mathring\mathcal{T}_{t_0}^{\mathrm{D},d,0}} = \widehat{\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}}\cup \widehat{\mathring\mathcal{T}_{t_0,\mathrm{R}}^{\mathrm{D},d}}$ is $\mathrm{T}$-connected since $\widehat{\mathring\mathcal{T}_{t_0,\mathrm{L}}^{\mathrm{D},d}}$ and $\widehat{\mathring\mathcal{T}_{t_0,\mathrm{R}}^{\mathrm{D},d}}$ both contain $\inf\{s\geq t_0: s\in\mathring\mathcal{J}^-\}$. This completes the proof of Assertion~\ref{cond:lem:def-wh-T-Dd-5}, since all the sets $\widehat{\mathring\mathcal{T}_{t_0}^{\mathrm{D},d,0}} $ in the union  as in the definition~\eqref{eq:def-wh-TtDd} of  $\mathring\mathcal{T}_{s_0}^{\mathrm{D},{d}}$ contain $s_0$.

\label{prop:Tutte5.8}
    For any $a\in (0,1)$, there is a $c\in (0,1)$ such that 
    \begin{equation}
        \mathbb{P}_\mathrm{E}[ \mathcal{J}^-_\mathrm{L}\cap [-2^n,(a-1)2^{n}]=\emptyset]\lesssim 2^{-cn}, \ \  \mathbb{P}_\mathrm{E}[ \mathcal{J}^-_\mathrm{L}\cap [(1-a)2^n,2^{n}]=\emptyset]\lesssim 2^{-cn}.
    \end{equation}
    The same also holds if we replace $\mathcal{J}_\mathrm{L}^-$ with $\mathcal{J}^-_\mathrm{R}$, or replace $\mathbb{P}_\mathrm{E}$ with $\mathbb{P}_\mathrm{Q}$.

\label{lem:gap-hat-J-Q}
     For $\alpha\in(1/2,1)$, for $c\in (0,2\alpha-1)$, we have 
    \begin{equation}\label{eq:lem:gap-hat-J-Q}\mathbb{P}_\mathrm{Q}\bigg[\exists \text{ interval } J\subseteq [-2^m,2^m], |J|=2^{\alpha m}, \mathring\mathcal{J}\cap J=\emptyset\bigg]\lesssim 2^{-cm}.\end{equation}

\label{lem:gap-hat-J}
    There exists $\varepsilon_0>0$ and $c\in(0,1)$ such that for any $n\in\mathbb{N}$, 
    \begin{equation}\label{eq:lem:gap-hat-J}\mathbb{P}_\mathrm{E}\bigg[\exists \text{ interval } J\subseteq [-2^n,2^n], |J|=2^{(1-\varepsilon_0)n}, \mathring\mathcal{J}\cap J=\emptyset\bigg]\lesssim 2^{-cn}.\end{equation}

Let $m\geq n$. By part~(\ref{cond:thm:KMT-0-cone-(ii)}) of Theorem~\ref{thm:KMT-0-cone}, for some constants $C_1,C_2>1$,  
\begin{equation} \label{eq:double-edge-lem-0-pf-1-00}\mathbb{P}_\mathrm{E}\big[ \sup_{t\in [-2^n,2^n]} \|\mathcal{Z}_t - Z_t\|\leq  C_1n  \big]\geq 1-C_22^{-n}.\end{equation}
Let $\varepsilon_3,\varepsilon_4 \in (0,\widetilde\varepsilon_1)$ and $\varepsilon_3<\varepsilon_4$. We  check that for large enough $n$, under the event
\begin{equation}\label{eq:double-edge-lem-0-pf-1}
    \begin{split}
        &\{\sup_{t\in [-2^n,2^n]}  \|\mathcal{Z}_t - Z_t\|\leq C_1n  \}  \cap \{\inf_{t\in [2^{(1-\widetilde\varepsilon_1)n},2^{n}]} L_t <- 2^{(1-\varepsilon_3)n/2} \} \\& \cap  \{  \inf_{t\in [-2^{n},-2^{(1-\widetilde\varepsilon_1)n}]} L_t < -2^{(1-\varepsilon_3)n/2}  \} \cap \{ \sup_{t\in [-2^{(1-\widetilde\varepsilon_1)n},2^{(1-\widetilde\varepsilon_1)n}]}\|Z_t\|<2^{(1-\varepsilon_4)n/2} \},
    \end{split}
\end{equation}
 for any $t_-,t_+\in\mathbb{R}$ such that $|t^-|\leq 2^{(1-\widetilde\varepsilon_1)n}$ and $t^+\geq 2^n$, the condition~\eqref{eq:double-edge-Mullin-A}   does not hold. Denote the four events in~\eqref{eq:double-edge-lem-0-pf-1} by $E_1 ,E_2 ,E_3 ,E_4 $, respectively. Then for large enough $n$, under $E_1 \cap E_4 $, $\mathcal{L}_{t^-}>-2^{(1-\varepsilon_4)n/2+1}$, whereas under $E_1 \cap E_2 \cap E_3$, we have $\inf_{t^-\leq t\leq t^+} \mathcal{L}_t<-2^{(1-\varepsilon_3)n/2-1}$. In particular, condition~\eqref{eq:double-edge-Mullin-A} does not hold. Similarly, under the event~\eqref{eq:double-edge-lem-0-pf-1}, there does not exist $t^-\leq -2^n$ and $|t^+|\leq  2^{(1-\widetilde\varepsilon_1)n}$ such that~\eqref{eq:double-edge-Mullin-A} holds. Therefore it suffices to prove $\mathbb{P}_\mathrm{E}\big[ E_1 \cap E_2 \cap E_3 \cap E_4 \big]\geq 1-\widetilde c_12^{-\widetilde c_2n}$ for some $\widetilde c_1,\widetilde c_2>0$. By~\eqref{eq:double-edge-lem-0-pf-1-00}, $\mathbb{P}_\mathrm{E}[E_1 ]\geq 1-C_22^{-n}$, and  {by Lemma ~\ref{lem:L_t-inf-a1a2}}, $\mathbb{P}_{\mathrm{E}}[E_2]\geq 1-c_2'2^{-c_2''n}$ and $\mathbb{P}_{\mathrm{E}}[E_3]\geq 1-c_3'2^{-c_3''n}$, and finally by  {Lemma~\ref{lem:L_t-inf-1}},  $\mathbb{P}_\mathrm{E}[E_4 ]\geq 1-c_4'2^{-c_4''n}$ for some constants $c_2',c_2'',c_3',c_3'',c_4',c_4''>0$. This completes the proof.

We choose $\lambda>0$ and $p>1-2\beta$ such that $c_2':=3-(2(\lambda+p)+6\beta+3\varepsilon_1)>0$.

By the definition of the boundary length process, \begin{equation}\label{eq:bdryprocess}\nu_h(\partial\eta([t_1,t_2])) = (L_{t_2}-L_{t_1})+(R_{t_2}-R_{t_1})-2\inf_{s\in[t_1,t_2]}(L_s-L_{t_1})-2\inf_{s\in[t_1,t_2]}(R_s-R_{t_1}).\end{equation}
    Since under $\mathbb{P}_\mathrm{Q}$, $(L,R)$ evolves as standard 2D Brownian motion, by Lemma~\ref{lem:BM-e3}, the Brownian scaling and a union bound,  
    \begin{equation}\label{eq:lem:BM-e4-11}
        \mathbb{P}_\mathrm{Q}\big[\, \exists\, t_1,t_2\in [-2^{\lambda n},2^{\lambda n}]\cap 2^{-pn}\mathbb{Z}: |t_1-t_2|\geq 2^{-\varepsilon_1n-1} \ \text{and }   \nu_h(\partial\eta([t_1,t_2]))\leq 2^{(\beta-\frac{1}{2})n+1}  \big]\lesssim 2^{2(\lambda+p)n}\cdot 2^{6(\beta+\frac{\varepsilon_1-1}{2})n}.
    \end{equation}
    Moreover, by standard estimates of the Brownian motion and a union bound, since $p>1-2\beta$, for some constant $c_1'>0$,
      \begin{equation}\label{eq:lem:BM-e4-22}
        \mathbb{P}_\mathrm{Q}\big[\, \exists\, t_1\in [-2^{\lambda n},2^{\lambda n}]\cap 2^{-pn}\mathbb{Z}:  \sup_{s\in[t_1-2^{-pn},t_1+2^{-pn}]}\|Z_s-Z_{t_1}\|\geq 2^{(\beta-\frac{1}{2})n-6} \big]\lesssim 2^{(\lambda+p)n}\cdot 2^{-c_1'n^2}.
    \end{equation}
    Then by~\eqref{eq:lem:BM-e4-11} and~\eqref{eq:lem:BM-e4-22} and the definition of $c_2'$, we have
    \begin{equation*}
         \mathbb{P}_\mathrm{Q}\big[\, \exists\, t_1,t_2\in [-2^{\lambda n},2^{\lambda n}]: |t_1-t_2|\geq 2^{-\varepsilon_1n} \ \text{and }   \nu_h(\partial\eta([t_1,t_2]))\leq 2^{(\beta-\frac{1}{2})n}  \big]\lesssim 2^{-c_2'n}.
    \end{equation*}
     {Finally, by Lemma~\ref{lem:SLE-contain-2}, for some $c_2''>0$, we have}
    \begin{equation*}
        \mathbb{P}_\mathrm{Q}[\mathbb{D}\nsubseteq \eta([-2^{\lambda n},2^{\lambda n}]) ]\lesssim 2^{-c_2''n}.
    \end{equation*}
    Therefore by a union bound, for some $c_1,c_2>0$, under $\mathbb{P}_\mathrm{Q}$, with probability at least $1-c_12^{-c_2n}$, there cannot be $t_1<t_2$ such that $\eta([t_1,t_2])\subseteq \mathbb{D}$, $|t_1-t_2|\geq 2^{-\varepsilon_1n}$ and $\nu_h(\partial\eta([t_1,t_2]))\leq 2^{(\beta-\frac{1}{2})n}$.
    The lemma then follows by reparameterizing $\eta$ via Lebesgue measure.

Let $\widetilde\varepsilon_0,\widetilde\varepsilon_2$ be as in Lemma~\ref{lem:gap-hat-J-9-4}, and $F^{2,n}$ be the corresponding event considered in Lemma~\ref{lem:gap-hat-J-9-4}.  We set $\varepsilon_0 = \frac{1}{3} ( \widetilde\varepsilon_0\wedge\widetilde\varepsilon_2)$.  

  Let $F^{1,n}$ be the event that there does not exist any $t_1,t_2$ with $|t_1|\leq 2^{(1-\widetilde\varepsilon_2)n}$ and $t_2\in\mathbb{R}$ such that $|t_2-t_1|\geq 2^{(1-\varepsilon_0) n-1}$ and  ~\eqref{eq:double-edge-Mullin-A} holds for $(t_1\wedge t_2,t_1\vee t_2)$ in place of $(t^-,t^+)$. Since $\varepsilon_0<\widetilde\varepsilon_2$,   Lemma~\ref{lem:gap-hat-J-9-3} and a scaling imply that $1-\mathbb{P}_\mathrm{E}[F^{1,n}]\lesssim 2^{-c''n}$ for some $c''>0$. Then under $F^n:=F^{1,n}\cap F^{2,n}$, there does not exist any $t^-,t^+\in [-2^n,2^n]$ such that $t^+-t^-\geq 2^{(1-\varepsilon_0)n-1}$ and~\eqref{eq:double-edge-Mullin-A} holds. Consider the event $\cap_{m=n}^\infty F^m$. If there exists $J\subseteq [-2^n,2^n]$ such that $|J|=2^{(1-\varepsilon_0)n}$ and $J\cap \mathring \mathcal{J}=\emptyset$, then by Lemma~\ref{lem:hat},  there exists $[t^-,t^+]$ such that $J\subseteq [t^-,t^+]$ and~\eqref{eq:double-edge-Mullin-A} holds. Then we have the following two possibilities:
  \begin{itemize}
      \item $|t^-|,|t^+|\leq 2^{n+1}$. Then $t^+-t^-\geq 2^{(1-\varepsilon_0)n}\geq 2^{(1-\varepsilon_0)(n+1)-1}$, and therefore $F^{n+1}$ does not happen;
      \item $|t^-|\vee|t^+|\geq 2^{n+1}$. Suppose for some $m\geq n+1$, $|t^-|\vee|t^+| \in [2^m,2^{m+1}]$. Then $t^+-t^-\geq 2^{m-1}\geq 2^{(1-\varepsilon_0)(m+1)-1}$, and therefore $F^{m+1}$ does not happen.
  \end{itemize}
  Therefore the event in~\eqref{eq:lem:gap-hat-J} does not happen under the event $\cap_{m=n}^\infty F^m$. The proposition then follows from Lemma~\ref{lem:gap-hat-J-9-3}, Lemma~\ref{lem:gap-hat-J-9-4} and a union bound.

\label{lem:gap-hat-J^-}
    There exists $\varepsilon_1>0$ and $c\in(0,1)$ such that for any $m\in\mathbb{N}$, 
    \begin{equation}\label{eq:lem:gap-hat-J^-}\mathbb{P}_\mathrm{E}\bigg[\exists \text{ interval } J\subseteq [-2^m,2^m], |J|=2^{(1-\varepsilon_1)m}, \mathring\mathcal{J}^-\cap J=\emptyset\bigg]\lesssim 2^{-cm}.\end{equation}
    In particular, for any $a_1>a_2>0$, 
\begin{equation}\label{eq:gap-hat-J^--a1a2}
    \mathbb{P}_\mathrm{E}\Big[\mathring\mathcal{J}^-\cap [-2^{a_1m},-2^{a_2m}]=\emptyset  \Big]\lesssim 2^{-cm}.
\end{equation}
    Furthermore, there exists $c_0,c>0$, such that 
     \begin{equation}\label{eq:jump-hat-J^-}\mathbb{P}_\mathrm{E}\big[\mathring N_\mathrm{L}[-2^m,2^m]\geq c_0m\big]\lesssim 2^{-cm}; \ \ \ \ \mathbb{P}_\mathrm{E}\big[\mathring N_\mathrm{R}[-2^m,2^m]\geq c_0m\big]\lesssim 2^{-cm}.  \end{equation}


     The same conclusions hold if we replace $\mathbb{P}_\mathrm{E}$ by $\mathbb{P}_\mathrm{Q}$.

Fix $N\in\mathbb{N}$. Consider a simple random walk $(\mathcal{X}_n,\mathcal{Y}_n)_{n=0,...,N}$ on $\mathbb{Z}^2$ of $N$ steps. For all $n^-<n^+$ such that \begin{equation}\label{eq:pi/2-excursion-AA}\mathcal{X}_{n^-}=\mathcal{X}_{n^+} = \inf_{n^-\leq j\leq n^+}\mathcal{X}_j, \ \ \mathcal{Y}_{n^-}=\mathcal{Y}_{n^+}=\inf_{n^-\leq j\leq n^+}\mathcal{Y}_j,\end{equation}  we erase all the times in $(n^-,n^+]$ from $[0,N]\cap\mathbb{Z}$ as in the definition of $\Phi_{\rm simple}$ and let $\mathcal{N}$ be the retained set consisting of $0=\sigma_1<\sigma_2<\cdots$.  Let $\widetilde E^{\uparrow}_{N,m}$ be the event that there exists at least $m$ times in $\mathcal{N}$, such that $\mathcal{X}_{\sigma_1}\leq ... \leq \mathcal{X}_{\sigma_m}$, $\mathcal{Y}_{\sigma_1}\leq ... \leq \mathcal{Y}_{\sigma_m}$. We prove that for each $N$, \begin{equation}\label{eq:pf-lem-Ex-111112}\mathbb{P}[\widetilde E^{\uparrow}_{N,m}]\leq (\frac{15}{16})^{m-1}.\end{equation}  


Let $1\leq j<m$ and we condition on $(\mathcal{X}_n,\mathcal{Y}_n)_{0\leq n\leq \sigma_j}$ and $(\sigma_1,...,\sigma_j)$ where $(\mathcal{X}_{\sigma_i},\mathcal{Y}_{\sigma_i})_{0\leq i\leq j}$ are nondecreasing in both coordinates. Then $(\mathcal{X}_n,\mathcal{Y}_n)_{\sigma_j\leq n\leq N}$ has the law as a simple random walk started from $(\mathcal{X}_{\sigma_j},\mathcal{Y}_{\sigma_j})$ and stopped at time $N-\sigma_j$, conditioned on the event $E_{\sigma_1,...,\sigma_j}^N$ that there does not exist any $1\leq i< j$ and $t\in(\sigma_j,N]$ such that $\mathcal{L}_{\sigma_i} = \mathcal{L}_{t} = \inf_{\sigma_i\leq u\leq t}\mathcal{L}_u$ and $\mathcal{R}_{\sigma_i} = \mathcal{R}_{t} = \inf_{\sigma_i\leq u\leq t}\mathcal{R}_u$. The reason is, for any trace of  $(\mathcal{X}_n,\mathcal{Y}_n)_{n=0,...,N}$ with given  $(\mathcal{X}_n,\mathcal{Y}_n)_{0\leq n\leq \sigma_j}$ and $(\sigma_1,...,\sigma_j)$, if the above equality does hold for some $i<j$ and $t\in(\sigma_j,N]$, then the time $\sigma_j$ would be erased and cannot remain in $\mathcal{N}$; if the event $E_{\sigma_1,...,\sigma_j}^N$ holds, then there cannot be $n^-<\sigma_i\leq n^+$ for $i\leq j$ such that~\eqref{eq:pi/2-excursion-AA} holds. Indeed, if this is not the case, then $(\mathcal{X}_{n^-},\mathcal{Y}_{n^-})$ must be equal to   $(\mathcal{X}_{\sigma_{i'}},\mathcal{Y}_{\sigma_{i'}})$ with $i'$ being the largest index with $\sigma_{i'}\leq n^-$ since  $(\mathcal{X}_{\sigma_i},\mathcal{Y}_{\sigma_i})_{0\leq i\leq j}$  are nondecreasing in both coordinates, and this  contradicts with the existing condition on $(\mathcal{X}_n,\mathcal{Y}_n)_{0\leq n\leq \sigma_j}$ and our event $E_{\sigma_1,...,\sigma_j}^N$. Now we assume that $j\geq 2$, $\sigma_j+2\leq N$ and $\mathcal{X}_{\sigma_{j}}=\mathcal{X}_{\sigma_{j-1}}$. Let   $A_j:=\{\mathcal{X}_{\sigma_j+1}-\mathcal{X}_{\sigma_j}=-1,\mathcal{X}_{\sigma_j+2}-\mathcal{X}_{\sigma_j+1}=1\}$. For a walk started from $(\mathcal{X}_{\sigma_j},\mathcal{Y}_{\sigma_j})$ that is in the event $E_{\sigma_1,...,\sigma_j}^{N-2}$, if we insert two steps $(-1,0),(1,0)$ at the beginning, then we get a walk that is in $E_{\sigma_1,...,\sigma_j}^{N}\cap A_j$. Therefore $\mathbb{P}[A_j\cap E_{\sigma_1,...,\sigma_j}^{N}]\geq \frac{1}{16}\mathbb{P}[E_{\sigma_1,...,\sigma_j}^{N-2}]\geq \frac{1}{16}\mathbb{P}[E_{\sigma_1,...,\sigma_j}^{N}]$ where the factor $\frac{1}{16}$ is from the insertion map and the last inequality is from the fact that $ E_{\sigma_1,...,\sigma_j}^{N}$ is decreasing over $N$. This gives $\mathbb{P}[A_j|E_{\sigma_1,...,\sigma_j}^{N}]\geq \frac{1}{16}$. Furthermore, under the event $A_j$, any excursion starting before $\sigma_j$ that erases $\sigma_j+1$ would also erase $\sigma_j$, while there cannot be any excursion starting at $\sigma_j$ that erase $\sigma_j+1$, and therefore $\sigma_{j+1}=\sigma_j+1$ and $\widetilde E^{\uparrow}_{N,j+1}$ no longer holds. This proves that \begin{equation}\label{eq:pf-lem-Ex-111}\mathbb{P}[\widetilde E^{\uparrow}_{N,j+1}| \widetilde E^{\uparrow}_{N,j},(\mathcal{X}_n,\mathcal{Y}_n)_{0\leq n\leq \sigma_j},(\sigma_1,...,\sigma_j)]\leq\frac{15}{16}.\end{equation}
  If $\sigma_j+1 = N$ or $j=1$, we can directly work with the event that the first step of the walk $(\mathcal{X}_n,\mathcal{Y}_n)_{\sigma_j\leq n\leq N}$ is $(-1,0)$ and~\eqref{eq:pf-lem-Ex-111} holds with $3/4$ in place of $15/16$. If $\sigma_j=N$, then the continuation is not possible and the conditional probability is 0. The case where $\mathcal{Y}_{\sigma_{j}}=\mathcal{Y}_{\sigma_{j-1}}$ follows similarly. This proves~\eqref{eq:pf-lem-Ex-111112}. 

  Since $\mathcal{J}$ is a  {unit rate} Poisson point process under the measure $\mathbb{P}_\mathrm{Q}$, $\mathbb{P}_\mathrm{Q}[\#\{\mathcal{J}\cap [-2^k,2^k]\}\geq 2^{1.1k}]\leq 2^{-k^2}$.  Using description of the $\mathcal{Z}$ as in part~(\ref{cond:prop:KMT-gamma-cone-(i)}) of Theorem~\ref{prop:KMT-gamma-cone}, by a union bound over all the starting and ending positions in $\mathcal{J}\cap [-2^k,2^k]\supseteq \mathcal{J}\cap I(k)$ and ~\eqref{eq:pf-lem-Ex-111112}, with probability at least $1-(2^{2.2k}\cdot \big(\frac{15}{16}\big)^{m-1}+2^{-k^2})$, uniformly over all possible realizations of $I(k)\subseteq [-2^k,2^k]$, the event $E^{\uparrow}_{k,m}$ does not happen.
 Therefore \begin{equation}
      \mathbb{P}_\mathrm{Q}[E^{\uparrow}_{k,m}]\leq 2^{2.2k}\cdot \big(\frac{15}{16}\big)^{m-1}+2^{-k^2},
  \end{equation}
which gives the claim.

\label{lem:T_t^h}
    Let $k\in\mathbb{N}$ and $h>0$. Suppose  
    \begin{equation}\label{eq:lem:T_t^h}
        d\,\sup_{t\in [-2^{k+1},2^{k+1}]}|L_t-\mathcal{L}_t|+2d<\frac{h}{8}, \ \ \  \ d\,\sup_{t\in [-2^{k+1},2^{k+1}]}|R_t-\mathcal{R}_t|+2d<\frac{h}{8}, \ \ \  {\mathring\mathcal{J}^-\cap(-2^{k+1},-2^k)\neq\emptyset},
    \end{equation}
   and in addition,
    \begin{equation}\label{eq:lem:T_t^h-1}
       d\cdot \mathring N_\mathrm{L}[-2^{k+1},2^{k+1}]+1\leq \frac{h}{8}, \ \ d\cdot \mathring N_\mathrm{R}[-2^{k+1},2^{k+1}]+1\leq \frac{h}{8},  
    \end{equation}
    then for any $t\in\mathring\mathcal{J}^-$ such that $\mathring\mathcal{T}_t^{\mathrm{D},d }\subseteq I(k)$, it holds that $ \mathring\mathcal{T}_t^{\mathrm{D},d }\subseteq  \mathring\mathcal{T}_t^{h,\infty}$.

