    \begin{equation}\label{eq:pf-eq:lem:T_t^h-1} \mathring\Delta_{t_0,\mathrm{L}}^{\mathrm{D},d} = d\cdot\mathring\Delta_{ \mathrm{L}}[t_0,\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{D},d}]=  d\sup_{s\in[t_0,\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{D},d}]}|(\mathcal{L}_s-L_s)-(\mathcal{L}_{t_0}-L_{t_0})|+2d+ d\mathring N_\mathrm{L}[t_0,\mathring\tau_{t_0,\mathrm{L}}^{\mathrm{D},d}] <\frac{h}{2}.\end{equation}
