\end{align}  \label{cond:thm:conv-0-cone-pack-Hcell-(ii)}
where the limit~\eqref{eq:E-curve-pack} is uniform over all choices of the space-filling curve ${\mathfrak{tr}}$ such that ${\mathfrak{tr}}(t)$ is within the corresponding  embedded face. 
\item For every $\varepsilon>0$, a.s.\ for each large enough $r>0$, we have the following. For every $s,t\in\mathring\mathcal{J}$ such that $\eta([s,t])\subseteq B(0;r)$, in the disk triangulation $  T_{s,t}$, there exists (not necessarily distinct) points $z_{s_{1,\mathrm{L}}},z_{s_{2,\mathrm{L}}},...,z_{s_{i_1,\mathrm{L}}}$ on the left boundary of $\eta((-\infty,s]))$ aligned from right to left, $z_{s_{1,\mathrm{R}}},z_{s_{2,\mathrm{R}}},...,z_{s_{i_2,\mathrm{R}}}$ on the right boundary of $\eta((-\infty,s]))$ aligned from left to right,  $z_{t_{1,\mathrm{L}}},z_{t_{2,\mathrm{L}}},...,z_{t_{j_1,\mathrm{L}}}$ on the left boundary of $\eta((-\infty,t]))$ aligned from right to left, $z_{t_{1,\mathrm{R}}},z_{t_{2,\mathrm{R}}},...,z_{t_{j_2,\mathrm{R}}}$ on the right boundary of $\eta((-\infty,t]))$ aligned from left to right, such that for $x\in\{s,t\}$, $q\in\{\mathrm{L},\mathrm{R}\}$, the distance between each $z_{x_{k,q}}$ and the center of the disk for $\mathfrak{v}_{x_{k,q}}$ is less than $\varepsilon r$, and the diameter of the segment of $\partial\eta((-\infty,x])$ between $z_{x_{k,q}}$ and $z_{x_{k-1,q}}$ is less than $\varepsilon r$, where we define $z_{x_{0,q}} = \eta(x)$. Furthermore, the segment of $\partial\eta((-\infty,s])$ between $z_{s_{i_1,\mathrm{L}}}$  (resp.\ $z_{s_{i_2,\mathrm{R}}}$) and $z_{s,t,\mathrm{L}}^-$  (resp.\ $z_{s,t,\mathrm{R}}^-$) has diameter less than $\varepsilon r$, and the segment of $\partial\eta((-\infty,t])$ between $z_{t_{j_1,\mathrm{L}}}$  (resp.\ $z_{t_{j_2,\mathrm{R}}}$) and $z_{s,t,\mathrm{L}}^-$  (resp.\ $z_{s,t,\mathrm{R}}^-$)  has diameter less than $\varepsilon r$.  \label{cond:thm:conv-0-cone-pack-Hcell-(iii)} 

\item There is an absolute constant $C>0$, such that in the setting of claim (iii), the quantum length of the boundary segment of $\eta((-\infty,x])$ from $\eta(x)$ to $z_{x_{k,q}}$ is in $[k-C\log r,k+C\log r]$. Furthermore, if $z_{x_{k,q}}$ is on $\partial\eta((-\infty,s]))\backslash\partial\eta([s,t])$, then the quantum length of the segment of  $\eta((-\infty,s])$ from $z_{x_{k,q}}$ to $z_{s,t,q}^-$ is less than $C\log r$. \label{cond:thm:conv-0-cone-pack-Hcell-(iv)}
    \end{enumerate}

\label{thm:conv-0-cone-unif-Hcell}
    Under the probability measure $\mathbb{P}_\mathrm{E}$, the following is true.  There exists a conformal map $\varphi:\mathfrak{M}(M)\to \mathbb{C}$ such that the following is true.
    \begin{enumerate}
        \item Almost surely, \begin{align}
 &  \lim_{r\to\infty} \frac{1}{r}\sup\{ |\eta(t)-\varphi(\mathfrak{v}_t)|: t\in \mathcal{J}_\mathrm{L}^-,\eta(t)\in B(0;r)\} = 0; \label{eq:E-unif} \\  
 &  \lim_{r\to\infty} \frac{1}{r}\sup\{\mathrm{diam}(\varphi(\mathfrak{f}_t)): t\in\mathcal{J}_\mathrm{R}^-, \eta(t)\in B(0;r)\} =0; \label{eq:E-edge}   \\ & 
   \lim_{r\to\infty} \frac{1}{r}\sup\{ |\eta(t)-{\mathfrak{tr}}(t)|:\eta(t)\in B(0;r)\} = 0,\label{eq:E-curve-unif}
\end{align}
where the limit~\eqref{eq:E-curve-unif} is uniform over all choices of the space-filling curve ${\mathfrak{tr}}$ such that ${\mathfrak{tr}}(t)$ is within the corresponding  embedded face.  {Furthermore, for each $\varepsilon>0$, almost surely for sufficiently large $r>0$, if the embedded face $\varphi(\mathfrak{f}_{f})$ intersects $B(0;r)$, then $\mathrm{diam}(\varphi(\mathfrak{f}_{f}))<\varepsilon r$.}
\item Claims $($\ref{cond:thm:conv-0-cone-pack-Hcell-(iii)}$)$ and $($\ref{cond:thm:conv-0-cone-pack-Hcell-(iv)}$)$ of Theorem~\ref{thm:conv-0-cone-pack-Hcell} with $\mathcal{J}$ in place of $\mathring\mathcal{J}$ and ``the center of the disk for $\mathfrak{v}_{x_{k,q}}$" replaced by ``$\varphi(\mathfrak{v}_{x_{k,q}})$" are true.
    \end{enumerate}

\label{lem:construction-embed-cell-0}
  Let $s\in\mathcal{J}$.   For each $k\in\mathbb{N}$, let $z_{s_{k,\mathrm{L}}}$ be  defined as above.  Then we have
    \begin{enumerate}[(i)]
        \item  $z_{s_{1,\mathrm{L}}}, z_{s_{2,\mathrm{L}}},...$ are aligned from right to left on the left boundary of $\eta((-\infty,s])$ (some points may duplicate). 
        \item  The segment of the left boundary of $\eta((-\infty,s])$ between $z_{s_{k-1,\mathrm{L}}}$ and $z_{s_{k,\mathrm{L}}}$    is contained within the convex hull of $ H_{\widetilde s_{k,\mathrm{L}}}^{\mathrm{cell}}$, where $\widetilde s_{k,\mathrm{L}}\in\mathcal{J}_\mathrm{L}^-$ is any time such that $\widetilde s_{k,\mathrm{L}} = s_{k,\mathrm{L}}$ or $\{\widetilde s_{k,\mathrm{L}},s_{k,\mathrm{L}}\}\in\mathcal{E}_\mathrm{T}$ and we write $z_{s_{0,\mathrm{L}}}=\eta(s)$. \label{cond:lem:construction-embed-cell-0-(ii)}
     \item There exists an absolute constant $C>0$ such that almost surely,  for $n$ large enough, the following is true. Let $\ell_{s,k,\mathrm{L}}$ be quantum length of the boundary segment of $\eta((-\infty,s])$ from $\eta(s)$ to $z_{s_{k,\mathrm{L}}}$.   If $s,s_{k,\mathrm{L}}\in [-2^n,2^n]$, then $|\ell_{s,k,\mathrm{L}}-k|\leq Cn$.  \label{cond:lem:construction-embed-cell-0-(iii)}                                                                                                                                                                                                  
    \end{enumerate}
  The analogous statement is true with $\mathrm{R}$ instead of $\mathrm{L}$ and ``right" instead of ``left".

\label{thm:He-Schramm-extension-1}
   Let $D,\widetilde D\subsetneq \mathbb{C}$ be    {bounded Jordan} domains. Let $\{T^n\}_{n\geq1}$ be simple disk triangulations, $\mathcal{P}^n, \widetilde\mathcal{P}^n$ be circle embeddings of $T^n$, and $f^n$ be homeomorphisms from the carrier of $\mathcal{P}^n$ to that of $\widetilde\mathcal{P}^n$, sending  each $D_v\cap \mathrm{carrier}(\mathcal{P}^n)$ where  $v\in\mathcal{V} T^n$ to $\widetilde D_v\cap \mathrm{carrier}(\widetilde \mathcal{P}^n)$. Consider the following conditions:
   \begin{enumerate}[(I)]
    \item The maximal spherical diameter of the disks in $\mathcal{P}^n$ converges to 0 as $n\to\infty$; \label{cond:thm:He-Schramm-extension-1-(i)}
       \item The distance between  the union of boundary disks of $\mathcal{P}^n$ and $D$  converges to 0 as $n\to\infty$, in the sense that
       $$\lim_{n\to\infty}\max_{{D^n\in\partial\mathcal{P}^n}}\inf_{z\in D^n}d(z,\partial D) = 0,$$

       and the same holds for $\widetilde\mathcal{P}^n$ and $\widetilde D$ instead of $\mathcal{P}^n$ and $D$. Moreover, the maximal spherical diameter of the disks in $\widetilde\mathcal{P}^n$ intersecting $\mathbb{C}\backslash \overline{\widetilde D}$ converges to 0 as $n\to\infty$; \label{cond:thm:He-Schramm-extension-1-(ii)}                                                                                                                                                                                                                                                                                                                                                                                                        
       \item For some $p_0\in D$, for some $N_0>0$, the sequence $\{f^n(p_0):n\geq N_0\}$ is compact in $\widetilde D$; \label{cond:thm:He-Schramm-extension-1-(iii)}
       \item Let $\gamma_n$ (resp.\ $\widetilde \gamma_n$) be the loop formed by connecting the centers of adjacent boundary disks of $\mathcal{P}^n$ (resp.\ $\widetilde\mathcal{P}^n$) using straight line segments, i.e., $\gamma_n$ (resp.\ $\widetilde \gamma_n$) is the boundary of the carrier of $\mathcal{P}^n$ (resp.\ $\widetilde\mathcal{P}^n$). Then the distance~\eqref{eq:curve-metric-0} between $\gamma_n$ and $\partial D$ (resp.\ $\widetilde\gamma_n$ and $\widetilde\partial D$) tends to 0 as $n\to\infty$. \label{cond:thm:He-Schramm-extension-1-(iv)}
   \end{enumerate}
 Suppose Conditions (I)-(III) holds. Then Conditions (I) and (III) hold for $(\widetilde\mathcal{P}^n,\widetilde D)$ in place of $(\mathcal{P}^n,D)$, and there is   a subsequence of  $\{f^n\}$ converging to a conformal map $f:D\to\widetilde D$ uniformly on compact subsets of $D$. If we further assume Condition (IV) holds,    then the above convergence is  uniform  {in the sense of Definition~\ref{def:unif-convergence}.}

\label{thm:He-Schramm-sphere}
     Let $\{T^n\}_{n\geq1}$ be  disk triangulations, $\mathcal{P}^n, \widetilde\mathcal{P}^n$ be circle embeddings of $T^n$ in $\mathbb{C}$, and $f^n$ be homeomorphisms from the carrier of $\mathcal{P}^n$ to that of $\widetilde\mathcal{P}^n$, sending  each $D_v\cap \mathrm{carrier}(\mathcal{P}^n)$ where  $v\in\mathcal{V} T^n$ to $\widetilde D_v\cap \mathrm{carrier}(\widetilde \mathcal{P}^n)$. Assume the following hold:
     \begin{enumerate}[(I)]
         \item The maximal spherical diameter of disks as well as the bounded interstices  in $\mathcal{P}^n$ tends to 0 as $n\to\infty$;\label{cond:thm:He-Schramm-sphere-(i)}
         \item For every $R>0$, for large enough $n$, $B(0;R)\subseteq \mathrm{carrier}(\mathcal{P}^n)$; \label{cond:thm:He-Schramm-sphere-(ii)}
         \item For each $n$, $f^n(0)=0$ and $f^n(1)=1$. \label{cond:thm:He-Schramm-sphere-(iii)} 
     \end{enumerate}
     Then (I) and (II) above hold for $\widetilde\mathcal{P}^n$ in place of $\mathcal{P}^n$, and $f^n$ converges uniformly to the identity in the spherical metric, in the sense that for any $\varepsilon>0$, there exists some $N>0$, such that for  every $n>N$ and $z\in\mathrm{carrier}(\mathcal{P}^n)$, $d_{\mathrm{sp}}(f^n(z),z)<\varepsilon$.

\label{thm:He-Schramm-disk}
    Let $\widetilde T^n$ be disk triangulations, $v_1^n$ and $v_2^n$ be boundary vertices of $\widetilde T^n$, and $\ell^n$ be the clockwise boundary arc of $\partial\widetilde T^n$ from $v_1^n$ to $v_2^n$. Let $\gamma^n$ be a simple path on $\widetilde T^n$ that intersects $\ell^n$ only at $v_1^n$ and $v_2^n$. Let $ T^n\subseteq \widetilde T^n$ be the disk triangulation formed by $\ell^n$, $\gamma^n$ and vertices between $\ell^n$ and $\gamma^n$.  Let $v^n$ be an interior vertex of $ T^n$, and $\widetilde\mathcal{P}^n$ and $\mathcal{P}^n$ be circle packing of $\widetilde T^n$ and $T^n$ in $\mathbb{D}$ centered at $v^n$. Further assume  the following:
    \begin{enumerate}[(i)]
        \item The maximal diameter of disks in $\mathcal{P}^n$ tends to 0 as $n\to\infty$;
        \item The diameter of the union of the disks in $\mathcal{P}^n$ for vertices in $\gamma^n$ tends to 0 as $n\to\infty$.
    \end{enumerate}
    Let $\mathcal{P}_1^n$ be the restriction of $\widetilde\mathcal{P}^n$ to the disks for  vertices in $ T^n$, and $f^n$ be a homeomorphism between the  {carriers} of $\mathcal{P}^n$ and $\mathcal{P}_1^n$   sending  each $D_v\cap \mathrm{carrier}(\mathcal{P}^n)$ where  $v\in\mathcal{V} T^n$ to $\widetilde D_v\cap \mathrm{carrier}( \mathcal{P}_1^n)$.  Then the maximal diameter of disks in $\widetilde\mathcal{P}^n$ as well as the diameter of the union of disks in $\widetilde\mathcal{P}^n$ for vertices in $\gamma^n\cup(\widetilde T^n\backslash T^n)$ tends to 0 as $n\to\infty$, and there exists $\theta_n\in [0,2\pi)$ such that $e^{i\theta_n} f^n$ converges uniformly to the identity in the sense of Definition~\ref{def:unif-convergence}.

\label{def:CPtoMOT}
    We say that \emph{circle packing converges to mating of trees for $(\mathcal{Z}^n,Z^n)_{n\in\mathbb{N}}$} if the following is true.    {Let $a,b\in (0,1)$ with $a+b<1$, 
    let $I_{a,b}\subseteq  I$ be the closed interval such that the left (resp.\ right) endpoint of $I_{a,b}$ has distance $a|I|$ (resp.\ $b|I|$) from the left (resp.\ right) endpoint of $I$. Let $I'=[t_{a,b}^-,t_{a,b}^+]$, where $t_{a,b}^-$ (resp.\ $t_{a,b}^+$) is the smallest (resp.\ largest) time in $\mathring\mathcal{J}^{n}\cap I_{a,b}$. Let $t_{\rm mid}$ be the midpoint of $I_{a,b}$, and $t_{\rm mid}':=\inf\{u\geq t_{\rm mid}:u\in\mathring\mathcal{J}^{n,-}\}$.}  Consider the SLE-decorated LQG surface encoded by $Z^n|_{I}$ and restricted to the time $I'$ and embed it as $(\mathbb{D},h_{n,I'},\eta_{n,I'})$ such that $\eta_{n,I'}(t_{\rm mid})=0$ and $\eta_n$ starts from 1 (See Section~\ref{subsubsec:MatedCRT}). Consider the disk triangulation $ T_{n,I'}$ and the path ${\mathfrak{tr}}_{n,I'}$ on $\mathcal{F} T_{n,I'}$ from  $\Phi_\mathrm{T}(\mathcal{Z}^n|_{I'})$.   
    Consider the univalent circle packing $\mathcal{P}_{n,I'}$ for $ T_{n,I'}$ in $\mathbb{D}$ centered at the vertex $\mathfrak{v}_{t_{\rm mid}'}$ such that the disk for the left endpoint of the root edge (i.e., the edge corresponding to the smallest time in $I'$ in the sewing procedure) is tangent to $\partial\mathbb{D}$ at 1.
     Then for any deterministic $a,b$, we have:
    \begin{enumerate} 
    \item with probability tending to 1, the map $\Phi_\mathrm{T}(\mathcal{Z}^n|_{I'})$ has at least three vertices on the boundary, $\big||I'|- |I_{a,b}|\big|\to 0$ and  $|t_{\rm mid}'- t_{\rm mid}|\to0$ in probability as $n\to\infty$;\label{cond:def:CPtoMOT-0}
        \item the  maximal diameter of disks in $\mathcal{P}_{n,I'}$ tends to 0 in probability as $n\to\infty$;\label{cond:def:CPtoMOT-1}
        \item we have  $$\sup_{t\in I'}|\eta_{n,I'}(t)-{\mathfrak{tr}}_{n,I'}(t)| \to 0 \text{ in probability as } n\to\infty,$$ where the convergence is uniform over all choices of $\mathfrak{tr}$ such that ${\mathfrak{tr}}_{n,I'}(t)$ is on the corresponding embedded face; 
        \label{cond:def:CPtoMOT-2}
        \item let $\nu_{n,I'}$ be the measure on $\partial\mathbb{D}$ that assigns mass $\nu(n)$ to each of the tangent point of a disk in $\mathcal{P}_{n,I'}$ and $\partial \mathbb{D}$ where $\nu(n)>0$ is a constant. Then the Prokhorov distance between $\nu_{n,I'}$ and the LQG boundary length measure $\nu_{h_{n,I'}}$ tends to 0 in probability as $n\to\infty$.\label{cond:def:CPtoMOT-3}
    \end{enumerate}

\label{lem:def-cZ^n}
     Consider the setting above under one of the probability measures $\mathbb{P}_\mathrm{Q}$ or $\mathbb{P}_\mathrm{E}$. For each $n\in\mathbb{N}$ there is a process $\mathcal{Z}^n:\mathbb{R}\to\mathbb{R}^2$ such that 
     \begin{equation}
         ((2^{n/2}Z_{2^{-n}t})_{t\in\mathbb{R}}, 2^n\mathfrak{U},(\mathcal{Z}^n_{2^{-n}t})_{t\in\mathbb{R}}) \overset{d}{=} ((Z_t)_{t\in\mathbb{R}},  \mathfrak{U},(\mathcal{Z}_t)_{t\in\mathbb{R}}).
     \end{equation}
     Furthermore, $\mathcal{Z}^n$ is measurable with respect to $(Z, \mathfrak{U})$.

\label{prop:cZ^n-pack-Q}
    For each $n\in\mathbb{N}$ there is a probability measure on pairs $(Z^n,\mathcal{Z}^n)$ such that the following holds: 
    \begin{enumerate}[(i)]
        \item $(\mathcal{Z}_t^n)_{t\in [0,1]}$ is a continuous-time nearest-neighbor walk on $\mathbb{Z}^2$ with rate $2^n$ such that $\mathcal{Z}_0^n=0$;
        \item $(Z^n_t)_{t\in[0,1]}$ has the law of a variance $\frac12$ uncorrelated 2D Brownian motion restricted to time $[0,1]$;
        \item Circle packing converges to mating of trees for $(\mathcal{Z}^n,Z^n)_{n\in\mathbb{N}}$ with $\nu(n)=2^{-n/2}$ in Condition~\ref{cond:def:CPtoMOT-3}, and for each compact set $K$ in Proposition~\ref{prop:cZ^n-pack-E} and any $\varepsilon>0$,                                                                                                                                                                      
        \begin{equation}
           \sup_{(a,b,a',b')\in K} \mathbb{P}\big[\mathrm{err}(\mathcal{Z}^n|_{[a',1-b']},Z^n|_{[a',1-b']},a,b)>\varepsilon \big]\to 0 \text{ as } n\to\infty.
        \end{equation}
        \label{cond:prop:cZ^n-pack-Q-(iii)}
        \item $\|Z^n-2^{-n/2}\mathcal{Z}^n\|_\infty$ converges to 0 in probability as $n\to\infty$.
    \end{enumerate}

\label{lem:cZ^n-pack-Q-n}
  Let $t_0>0$. There is a coupling of $Z,\mathcal{Z}^1,\mathcal{Z}^2,...$ such that the following holds: 
    \begin{enumerate}[(i)]
        \item For each $n$, $(\mathcal{Z}_t^n)_{t\in [0,t_0]}$ is a continuous-time nearest-neighbor walk on $\mathbb{Z}^2$ with rate $n$ such that $\mathcal{Z}_0^n=0$;
        \item $(Z_t)_{t\in[0,t_0]}$ has the law of a variance $\frac12$ uncorrelated 2D Brownian motion restricted to time $[0,t_0]$;
          \item $\|Z-n^{-1/2}\mathcal{Z}^n\|_\infty$ converges to 0 in probability as $n\to\infty$;
        \item Circle packing converges to mating of trees for $(\mathcal{Z}^n,Z)_{n\in\mathbb{N}}$ with $\nu(n)=n^{-1/2}$ in Condition~\ref{cond:def:CPtoMOT-3}, and for each compact set $K\subseteq\{(a,b,a',b'):a,b>0,a+b<1,a',b'\geq0, a'+b'\leq 0.3\}$ and $\varepsilon>0$,                                                                                                                                                                      
        \begin{equation}\label{eq:conv-dist-check}
           \sup_{(a,b,a',b')\in K} \mathbb{P}\big[\mathrm{err}(\mathcal{Z}^n|_{[a't_0,(1-b')t_0]},Z|_{[a't_0,(1-b')t_0]},a,b)>\varepsilon \big]\to 0 \text{ as } n\to\infty.
        \end{equation}\label{cond:lem:cZ^n-pack-Q-n-(iv)}

    \end{enumerate}

\label{lem:disk-pf-0}
      There is a coupling of $(Z,\widetilde\mathcal{Z}^1,\widetilde\mathcal{Z}^2,...)$ such that
    \begin{enumerate}[(i)]
    \item $Z:[0,A]\to\mathbb{R}_+^2$ has the law of  {$\frac{1}{2}$ times} a Brownian cone excursion  {of covariance~\eqref{eq:variance}} from $(2,0)$ to $(0,0)$ for random duration $A>0$ where $A$ has density $\rho(a) = a^{-3}e^{-1/a}$; \label{cond:lem:disk-pf-0-(i)}
        \item for each $n\in\mathbb{N}$, conditioned on $A=a$, $\widetilde\mathcal{Z}^n:[0,a]\to\mathbb{Z}^2$ is  a rate $n$ continuous-time nearest neighbor walk on $\mathbb{Z}^2$ started from $(\left\lceil  {\sqrt n}-1  \right\rceil,0)$ and ended at $(0,0)$, conditioned on  $\widetilde\mathcal{Z}^n_t\in\mathbb{R}_+^2$ for every $t\in [0,a]$;  \label{cond:lem:disk-pf-0-(ii)}
        \item {the total variation distance between the law of  $\Phi_\mathrm{T}^\mathrm{disk}(\widetilde\mathcal{Z}^n)=(\widetilde T^{\mathrm{disk},n},\widetilde\mathfrak{tr}^{\mathrm{disk},n})$  and the  law of  $(T^{\mathrm{disk},n},\mathfrak{tr}^{\mathrm{disk},n})$ in Theorem~\ref{thm:pack-disk} for $\ell=\left\lceil \sqrt n \right\rceil$ tends to 0 as $n\to\infty$ up to a reparameterization of the trace $\widetilde\mathfrak{tr}^{\mathrm{disk},n}$};  \label{cond:lem:disk-pf-0-(iii)}
        \item  {for each deterministic $\varepsilon\in(0,1/4)$,} circle packing converges to mating of trees for  {$(\widetilde\mathcal{Z}^n|_{[A\varepsilon,A(1-\varepsilon)]},Z|_{[A\varepsilon,A(1-\varepsilon)]})_{n\in\mathbb{N}}$}  with $\nu(n)=n^{-1/2}$ in Condition~\ref{cond:def:CPtoMOT-3};  \label{cond:lem:disk-pf-0-(iv)}
        \item $\|Z-n^{-1/2}\widetilde\mathcal{Z}^n \|_\infty \to 0 $ in probability as $n\to\infty$ and  \label{cond:lem:disk-pf-0-(v)}
        \item let $B^n = \{t\in [0,A]: \widetilde\mathcal{Z}_t^n-\lim_{u\uparrow t}\widetilde\mathcal{Z}_u^n \neq 0 \}$ denote the set of times at which $\widetilde\mathcal{Z}^n$ jumps, conditioned on $A$ and $\#B^n$, the elements of $B^n$ have the law of $\#B^n$ uniform and independent times in $[0,A]$. {Furthermore, $\#B^n/n$ converges to $A$ in probability as $n\to\infty$.}  \label{cond:lem:disk-pf-0-(vi)}
    \end{enumerate}

\label{lem:disk-pf-2}
    Let $(Z,\widetilde\mathcal{Z}^1,\widetilde\mathcal{Z}^2,...)$ and $\widetilde T^{\mathrm{disk},n}$ be as in Lemma~\ref{lem:disk-pf-0}. Let $\widetilde \mathfrak{tr}^n:[0,A]\to \mathcal{F} \widetilde T^{\mathrm{disk},n}$ be the path on faces of $\widetilde T^{\mathrm{disk},n}$.  Let $\mathfrak{v}^{\mathrm{mid},n}$ be the vertex on $\widetilde T^{\mathrm{disk},n}$ for the first downward jump time of  {$\Phi_{\rm simple}(\widetilde\mathcal{Z}^n)$} after $A/2$.   Then with probability tending to 1, $\mathfrak{v}^{\mathrm{mid},n}$ is not a boundary vertex. Further consider a univalent  circle packing $\widetilde\mathcal{P}^{\mathrm{disk},n}$ in $\mathbb{D}$ for $\widetilde T^{\mathrm{disk},n}$ centered at $\mathfrak{v}^{\mathrm{mid},n}$. Then up to a rotation, we have the following:
    \begin{enumerate}[(i)]
        \item The maximal diameter of disks in $\widetilde\mathcal{P}^{\mathrm{disk},n}$ tends to 0 in probability as $n\to\infty$;\label{cond:lem:disk-pf-2-(i)}
        \item Let $\widetilde\mathfrak{tr}^{\mathrm{disk},n}:[0,A]\to\overline\mathbb{D}$ be the path on faces of $\widetilde T^{\mathrm{disk},n}$ under the embedding $\widetilde\mathcal{P}^{\mathrm{disk},n}$. Then                        
        \begin{equation}\label{eq:lem:disk-pf-2}\sup_{t\in [0,A]} |\eta^\mathrm{disk}(t)-\widetilde\mathfrak{tr}^{\mathrm{disk},n}(t)|\to 0 \ \ \ \text{in probability as } n\to\infty. \end{equation} 
        and the limit is uniform over all choices of the trace $\widetilde\mathfrak{tr}^{\mathrm{disk},n}$ such that $\widetilde\mathfrak{tr}^{\mathrm{disk},n}(t)$ is on the embedded face. 
        \label{cond:lem:disk-pf-2-(ii)}
        \item  Let $\widetilde\nu^{\mathrm{disk},n}$ be the measure on $\partial\mathbb{D}$ that assigns mass $n^{-1/2}$ to each tangent point of disks in $\widetilde\mathcal{P}^{\mathrm{disk},n}$ and $\partial\mathbb{D}$. The Prohokov distance between $\widetilde\nu^{\mathrm{disk},n}$ and $\nu_{h^\mathrm{disk}}$ tends to 0 in probability as $n\to\infty$. \label{cond:lem:disk-pf-2-(iii)}
    \end{enumerate}

\label{lem:disk-pf-3}
    Let $\widetilde t^n_1\leq\widetilde t^n_2\leq...\leq \widetilde t^n_{\widetilde b^n}$ be the re-ordering of the set of times in $B^n$ from the smallest to largest. Then 
    \begin{equation}\label{eq:lem:disk-pf-3-1}\sup_{1\leq j\leq \widetilde b^n} |\widetilde t^n_j - \frac{Aj}{\widetilde b^n}|\to 0 \text{ in probability as } n\to\infty.\end{equation}
    Likewise, let $\widetilde s^n_1\leq\widetilde s^n_2\leq...\leq \widetilde s^n_{\widetilde a^n}$ be the re-ordering of the set of times $\mathfrak{t}^n_v$. Then
     \begin{equation}\label{eq:lem:disk-pf-3-2}\sup_{1\leq j\leq \widetilde a^n} |\widetilde s^n_j - \frac{Aj}{\widetilde a^n}|\to 0 \text{ in probability as } n\to\infty.\end{equation}

\label{lem:sph-pack-pf-1}
   There is a coupling of $(\widetilde\mathcal{Z}^n,Z)$ such that 
    \begin{enumerate}[(i)]
        \item $\widetilde\mathcal{Z}^n:[0,1]\to\mathbb{Z}^2$ has the same law as the process $\widetilde\mathcal{Z}^n$ in Lemma~\ref{lem:417};\label{cond:lem:sph-pack-pf-0-(i)}
         \item $Z:[0,1]\to\mathbb{R}_+^2$ has the law of $\frac{1}{2}$ times a Brownian cone excursion of duration $1$ in the first quadrant from $(0,0)$ to $(0,0)$ of covariance~\eqref{eq:variance};\label{cond:lem:sph-pack-pf-0-(ii)}
        \item for any $\delta\in(0,0.01)$, circle packing converges to mating of trees for $(\widetilde\mathcal{Z}^n|_{[\delta ,(1-\delta)]},Z|_{[\delta,(1-\delta)]})$ with $\nu(n)=(2n)^{-1/2}$; \label{cond:lem:sph-pack-pf-0-(iii)}
        \item $\|(Z-(2n)^{-1/2}\widetilde\mathcal{Z}^n)\|_\infty\to0 $ in probability as $n\to\infty$. \label{cond:lem:sph-pack-pf-0-(iv)}
    \end{enumerate}

Let $\widetilde \mathcal{Z}^n$ and $\mathcal{Z}^{\mathrm{sp},n}$ be the processes in Lemma~\ref{lem:417}. By classical results (e.g.~\cite{DIM77}), there exists a coupling $(\mathcal{Z}^{\mathrm{sp},n},Z)_{n\in\mathbb{N}}$ where $\mathcal{Z}^{\mathrm{sp},n}$ is  uniform from $\mathcal{A}_n^\mathrm{sp}$ and $Z$ is the Brownian excursion as in claim (ii) such that $\sup_{t\in[0,1]}|(Z_t-(2n)^{-1/2}\mathcal{Z}^{\mathrm{sp},n}_{\lfloor 2nt \rfloor})|\to 0$ in probability, which further implies that $\|(Z-(2n)^{-1/2}\widetilde\mathcal{Z}^n)\|_\infty\to0 $ in probability as $n\to\infty$.  Let $(\check{Z}, \check{\mathcal{Z}^1}, \check{\mathcal{Z}^2}, \check{\mathcal{Z}^3},\cdots)$ be the processes $(Z,\mathcal{Z}^2,\mathcal{Z}^4,\mathcal{Z}^6,\cdots)$ as in Lemma~\ref{lem:cZ^n-pack-Q-n}. Fix $\delta>0$.  Let $(Z^n,\mathcal{Z}^n)$ be $(\check Z,\check{\mathcal{Z}^n})$ whose law is weighted by the Radon-Nikodym derivative in Lemma~\ref{lem:417} such that $(\mathcal{Z}^n_t-\mathcal{Z}_{\delta}^n)_{t\in[\delta,1-\delta]}$ has the same law as $(\widetilde\mathcal{Z}^n_t-\widetilde\mathcal{Z}_{\delta}^n)_{t\in[\delta,1-\delta]}$. We may further couple $(Z^n,\mathcal{Z}^n,\widetilde\mathcal{Z}^n)_{n\in\mathbb{N}}$  such that $(\widetilde\mathcal{Z}^n_t-\widetilde\mathcal{Z}_{\delta}^n)_{t\in[\delta,1-\delta]} = (\mathcal{Z}^n_t-\mathcal{Z}_{\delta}^n)_{t\in[\delta,1-\delta]}$, and by Lemma~\ref{lem:cZ^n-pack-Q-n} and Lemma~\ref{lem:417},                                            
   $\|\big((2n)^{-1/2}\widetilde\mathcal{Z}^n-Z^n - ((2n)^{-1/2}\widetilde\mathcal{Z}^n_\delta-Z^n_\delta )\big)|_{[\delta,1-\delta]}\|_\infty\to 0$ in probability.                                                                                                                   

    By Lemma~\ref{lem:417}, for each deterministic $\delta\in(0,1)$, the law of $Z^n|_{[\delta,1-\delta]}$ is absolutely continuous with respect to that of $\check{Z}|_{[\delta,1-\delta]}$ with Radon-Nikodym derivative bounded by a constant $C_{\delta}$, and the claim on $\|\big((2n)^{-1/2}\widetilde\mathcal{Z}^n-Z^n - ((2n)^{-1/2}\widetilde\mathcal{Z}^n_\delta-Z^n_\delta )\big)|_{[\delta,1-\delta]}\|_\infty\to 0$   and  $\|(Z-(2n)^{-1/2}\widetilde\mathcal{Z}^n)\|_\infty\to0 $ in probability imply that $(Z_{t}^n-Z_\delta^n)_{t\in [\delta,1-\delta]}$ converges to $(Z_{t}-Z_\delta)_{t\in [\delta,1-\delta]}$ in probability under the uniform topology.  Now consider the metric $\mathfrak{d}$, the functions  $\widetilde F^n$, $\widetilde F^\infty$ and $\widetilde F_0^\infty$ defined below Definition~\ref{def:CPtoMOT}.  Then the bounded Radon-Nikodym derivative and the convergence of  $(Z_{t}^n-Z_\delta^n)_{t\in [\delta,1-\delta]}$  to $(Z_{t}-Z_\delta)_{t\in [\delta,1-\delta]}$ in probability implies that for each deterministic $a,b>0$ with $a+b<1$, \begin{equation}\label{eq:pf-418-00}
    \mathfrak{d}\big(\widetilde F_0^\infty(Z^n|_{[\delta,1-\delta]},a,b), \widetilde F_0^\infty(Z|_{[\delta,1-\delta]},a,b)\big)\to 0 \  \text{ in probability as }n\to\infty. \end{equation} To see this, by Lusin's theorem, for any $\zeta>0$, $(Z-Z_\delta)|_{[\delta,1-\delta]}\mapsto \widetilde F_0^\infty(Z |_{[\delta,1-\delta]},a,b)$ is continuous on a compact set $K_\zeta\subseteq C([\delta,1-\delta],\mathbb{R}^2)$ such that $\mu(K_\zeta^c)<\zeta$, where $\mu$ is the law of the unconditioned Brownian motion $(\check{Z}-\check{Z}_\delta)|_{[\delta,1-\delta]}$ and the SLE curve $\eta_{n,[\delta,1-\delta]}$ constructed by $Z^n|_{[\delta,1-\delta]}$ is defined to be constant over $[0,\delta]$ and $[1-\delta,1]$. Here we used the fact  that $Z|_{[\delta,1-\delta]}$ and $(Z-Z_\delta)|_{[\delta,1-\delta]}$ encodes the same quantum surface.  For any $\vartheta>0$,  there exists $\vartheta_1>0$ such that if $\|((Z^n-Z^n_\delta)-(Z-Z_\delta))|_{[\delta,1-\delta]}\|_\infty<\vartheta_1$ and  both $(Z-Z_\delta)|_{[\delta,1-\delta]},(Z^n-Z^n_\delta)|_{[\delta,1-\delta]}$ are in $K_\zeta$, then $\mathfrak{d}\big(\widetilde F_0^\infty(Z^n|_{[\delta,1-\delta]},a,b),\widetilde F_0^\infty(Z|_{[\delta,1-\delta]},a,b)\big)<\vartheta$.  Then  
    \begin{equation}\label{eq:418-pf-1}
    \begin{split}
              &\mathbb{P}\big[\mathfrak{d}\big(\widetilde F_0^\infty(Z^n|_{[\delta,1-\delta]},a,b),\widetilde F_0^\infty(Z|_{[\delta,1-\delta]},a,b)\big)\geq\vartheta \big]
              \leq \mathbb{P}\big[\|((Z^n-Z^n_\delta)-(Z-Z_\delta))|_{[\delta,1-\delta]}\|_\infty\geq\vartheta_1\big] \\&+ \mathbb{P}[(Z^n-Z^n_\delta)|_{[\delta,1-\delta]}\notin K_\zeta]+\mathbb{P}[(Z-Z_\delta)|_{[\delta,1-\delta]}\notin K_\zeta].
    \end{split}
    \end{equation} 
    For fixed $\zeta$, the first term on the right hand side of~\eqref{eq:418-pf-1} tends to 0, the second   tends to 0 as $\zeta\to 0$ uniformly over $n$ by the boundedness of Radon-Nikodym derivative from Lemma~\ref{lem:417}, and the third term tends to 0 as $\zeta\to 0$ since the law of $(Z-Z_\delta)|_{[\delta,1-\delta]}$ is absolutely continuous with respect to the unconditioned version. This gives the desired convergence in probability.

    Now using the convergence of circle packing to mating of trees for $(\check{\mathcal{Z}}^n,\check{Z})$ as in~\eqref{eq:conv-dist-check}, we have 
    $$\mathfrak{d}\big(\widetilde F^\infty(\check{Z}|_{[\delta,1-\delta]},\check{\mathcal{Z}^n}|_{[\delta,1-\delta]},a,b),\widetilde F^n(\check{\mathcal{Z}^n}|_{[\delta,1-\delta]},a,b)\big)\to 0 \text{ in probability as }n\to\infty. $$
    Further using the continuity of $\eta$ and the convergence of $|I'|\to |I_{a,b}|$ as in Condition~\ref{cond:def:CPtoMOT-0},  $\partial\eta(I')$ is close to $\partial\eta(I_{a,b})$ for large $n$ under the metric~\eqref{eq:curve-metric-0}, and therefore one can further use Proposition~\ref{prop:boundary-perturb} to prove that
     $$\mathfrak{d}\big(\widetilde F^\infty(\check{Z}|_{[\delta,1-\delta]},\check{\mathcal{Z}^n}|_{[\delta,1-\delta]},a,b),\widetilde F^\infty_0(\check{Z}|_{[\delta,1-\delta]}, a,b)\big)\to 0 \text{ in probability as }n\to\infty. $$

     By Lemma~\ref{lem:417}, 
     \begin{equation}\label{eq:pf-418-001}
         \mathfrak{d}\big(\widetilde F^\infty_0( {Z}^n|_{[\delta,1-\delta]}, a,b), \widetilde F^n(\widetilde{\mathcal{Z}}^n|_{[\delta,1-\delta]},a,b)\big)\to 0 \ \text{ in probability as }n\to\infty. 
     \end{equation}
     Therefore by~\eqref{eq:pf-418-00} and~\eqref{eq:pf-418-001}, 
     \begin{equation}\label{eq:pf-418-002}
         \mathfrak{d}\big(\widetilde F^\infty_0( {Z}|_{[\delta,1-\delta]}, a,b), \widetilde F^n(\widetilde{\mathcal{Z}}^n|_{[\delta,1-\delta]},a,b)\big)\to 0 \ \text{ in probability as }n\to\infty. 
     \end{equation}
     Further using the continuity of $\eta^\mathrm{sp}$ and the convergence of the interval length coordinate for the $\widetilde F$-function and the inclusion $I'\subseteq I_{a,b}$ in Condition~\ref{cond:def:CPtoMOT-0} in Definition~\ref{def:CPtoMOT}, one can again use Proposition~\ref{prop:boundary-perturb} to check that $\mathfrak{d}\big(\widetilde F^\infty_0( {Z}|_{[\delta,1-\delta]}, a,b), \widetilde F^\infty( {Z}|_{[\delta,1-\delta]},{\widetilde\mathcal{Z}^n}|_{[\delta,1-\delta]}, a,b)\big)\to 0$ in probability as $n\to\infty$. This implies that $$ \mathfrak{d}\big(\widetilde F^\infty( {Z}|_{[\delta,1-\delta]},{\widetilde\mathcal{Z}^n}|_{[\delta,1-\delta]},a,b), \widetilde F^n(\widetilde{\mathcal{Z}}^n|_{[\delta,1-\delta]},a,b)\big)\to 0 \ \text{ in probability as }n\to\infty. $$ This gives claim (iii) since the vanishing disk diameter in the packing and  the convergence of one space-filling trace $\mathfrak{tr}$ imply the convergence of all space-filling traces.

\label{lem:sph-pack-pf-4}
Let $\mathfrak{v}^{0,n} = \mathfrak{v}^n_{t^{0,n} }$, $\mathfrak{v}^{\mathrm{mid},n} = \mathfrak{v}^n_{t^{\mathrm{mid},n} }$ and     $\mathfrak{v}^{1/4,n} = \mathfrak{v}^n_{t^{1/4,n} }$, where $t^{0,n} = \inf\mathring B^{n,-}$, $t^{\mathrm{mid},n}  = \inf\{s\geq 1/2:s\in \mathring B^{n,-}\}$ and $t^{1/4,n}  = \inf\{s\geq 1/4:s\in \mathring B^{n,-}\}$. Let $ \mathcal{P}^{\mathrm{sp},n}$ be a circle packing in $\widehat\mathbb{C}$ for $ T^{\mathrm{sp},n}$ such that the disks for  $\mathfrak{v}^{\mathrm{mid},n}$ and $\mathfrak{v}^{1/4,n}$ are centered at  0 and 1, respectively. Let $\widetilde\mathfrak{tr}^{\mathrm{sp},n}:[0,1]\to \mathcal{F} \widetilde T^{\mathrm{sp},n}$ be the space-filling path on the faces of $ T^{\mathrm{sp},n}$, and suppose $\infty$ is contained within the interstice between disks for the face $\mathfrak{f}^{n,0}$ on $\Phi_{\rm simple}(T^{\mathrm{sp},n})$ containing $\mathfrak{tr}^{\mathrm{sp},n}(t^{0,n})$.  Then we have the following:
 \begin{enumerate}[(i)]
        \item With probability tending to 1 as $n\to\infty$, $\Phi_{\rm simple}(T^{\mathrm{sp},n})$ is non-empty and $ \mathcal{P}^{\mathrm{sp},n}$ is well-defined, and the maximal spherical diameter of disks in $ \mathcal{P}^{\mathrm{sp},n}$ tends to 0 in probability as $n\to\infty$;
        \item Let $\widetilde\mathfrak{tr}^{\mathrm{sp},n}:[0,1]\to \widehat\mathbb{C}$ be the path on faces of $ T^{\mathrm{sp},n}$ under the embedding $ \mathcal{P}^{\mathrm{sp},n}$. Then
        \begin{equation}\label{eq:lem:sph-pack-pf-4}\sup_{t\in [0,1]} d_{\mathrm{sp}}( \eta^\mathrm{sp}(t),\widetilde\mathfrak{tr}^{\mathrm{sp},n}(t))\to 0 \ \ \ \text{in probability as } n\to\infty, \end{equation}
        where the convergence is uniform over all choices of the space-filling path $\widetilde\mathfrak{tr}^{\mathrm{sp},n}$.

    \end{enumerate}

\label{lem:sph-pack-pf-5}
    Let $\widetilde t^n_1\leq\widetilde t^n_2\leq...\leq \widetilde t^n_{2n}$ be the re-ordering of the set of times in $\widetilde B^n$ from the smallest to largest. Then 
    \begin{equation}\label{eq:lem:sph-pf-5-1}\sup_{1\leq j\leq  2n} |\widetilde t^n_j - \frac{j}{2n}|\to 0 \text{ in probability as } n\to\infty.\end{equation}
    Likewise, let $\widetilde s^n_1\leq\widetilde s^n_2\leq...\leq \widetilde s^n_{n+2}$ be the re-ordering of the set of times $\mathfrak{t}_v^n$. Then
     \begin{equation}\label{eq:lem:sph-pf-5-2}\sup_{1\leq j\leq n+2} |\widetilde s^n_j - \frac{j}{ n+2}|\to 0 \text{ in probability as } n\to\infty.\end{equation}

Let $\Phi_\mathrm{T}(\widetilde\mathcal{Z}^n) = (\widetilde T^n,\widetilde\mathfrak{tr}^n)$.                                                                                                                                                                           
    Since the convergence in Lemma~\ref{lem:cZ^n-pack-Q-n} is invariant if we shift and translate the walks, we see that the conclusions in  Lemma~\ref{lem:cZ^n-pack-Q-n} hold for  $(Z,(\widetilde\mathcal{Z}^n)_{n\in\mathbb{N}})$ for the interval $[-2,2]$ in place of $[0,a]$. Let $\mathring\mathcal{J}^{n,-}$ be the time set $\mathring\mathcal{J}^-$ defined for the walk $\widetilde\mathcal{Z}^n$ as before Lemma~\ref{lem:A2}.   By Proposition~\ref{lem:gap-hat-J^-} and scaling, for some $\alpha\in (0,1/2)$, with probability tending to 1 as $n\to\infty$, every interval $J\subseteq [-2,2]$ of length at least $n^{-\alpha}$ contains at least one element of $\mathring\mathcal{J}^{n,-}$.  Let $t_n^- = \inf\{s\geq -1:s\in \mathring\mathcal{J}^{n}\}$, $t_n^+=\sup\{s\leq 1:s\in \mathring\mathcal{J}^{n}\}$ and $I_n'=[t_n^-,t_n^+]$. 

   Let $j\in\mathbb{N}$. By Lemma~\ref{lem:cZ^n-pack-Q-n}, circle packing converges to mating of trees for $(\widetilde\mathcal{Z}^{jn}|_{[-2,2]},Z|_{[-2,2]})$, and let $(\widetilde T^{n,j},\widetilde\mathfrak{tr}^{n,j}) = \Phi_\mathrm{T}(\widetilde\mathcal{Z}^{jn}|_{I_{jn}'})$. Let $\mathfrak{v}^{n,j,0}$ (resp.\ $\mathfrak{v}^{n,j,1}$) be the vertex for the time $\inf(\mathring\mathcal{J}^{jn,-}\cap\mathbb{R}_+)$ (resp.\ $\inf(\mathring\mathcal{J}^{jn,-}\cap [1/j,\infty))$) in the map $\widetilde T^{n,j}$, $\mathcal{P}^{n,j}$ be a circle packing in $\mathbb{D}$ for $\widetilde T^{n,j}$ centered at $\mathfrak{v}^{n,j,0}$ as in Definition~\ref{def:CPtoMOT}.    Let $\varphi_{n,j}:\eta(I_{jn}')\to\mathbb{D}$ (resp.\  $\varphi:\eta([-1,1])\to\mathbb{D}$) be the conformal map fixing 0 such that $\varphi_{n,j}'(0)>0$ (resp.\ $\varphi'(0)>0$).  Then it follows from Proposition~\ref{lem:gap-hat-J^-}, Definition~\ref{def:CPtoMOT} along with Proposition~\ref{prop:boundary-perturb}, up to a rotation of $\mathcal{P}^{n,j}$, there exists $\varepsilon_{n,j}>0$ such that with probability tending to 1 as $n\to\infty$, the following holds:
   \begin{enumerate}[(i)]
      \item for each fixed $j$, $\varepsilon_{n,j}\to 0$ as $n\to\infty$;
       \item  the maximal diameter of disks in $\mathcal{P}^{n,j}$ is less than $\varepsilon_{n,j}$;
       \item  for all choices of the embedded space-filling curve $\widetilde\mathfrak{tr}^{n,j}$ and $t\in I_{jn}'$,
       \begin{equation}\label{eq:CONE-1-new}
           |\varphi_{n,j}(\eta(t))-\widetilde\mathfrak{tr}^{n,j}(t)|\leq \varepsilon_{n,j} \text{ and } |\varphi_{n,j}(\eta(t))-\varphi(\eta(t))|<\varepsilon_{n,j},                        
       \end{equation}
