   \end{enumerate}

    Now let $R^{n,j}>0$ and $\theta^{n,j}\in\mathbb{R}$, such that in the circle packing  $\widetilde\mathcal{P}^{n,j}:= R^{n,j}e^{i\theta^{n,j}}\mathcal{P}^{n,j}$,    the disks for $\mathfrak{v}^{n,j,0}$ and $\mathfrak{v}^{n,j,1}$ are centered at 0 and 1, respectively. Then following Proposition~\ref{lem:gap-hat-J^-} and the claims above,                                                                                                      
    \begin{equation}\label{pf:lem:pf-pack-cone-2-N1} |(R^{n,j})^{-1}e^{-i\theta^{n,j}} - \varphi(\eta(1/j))|\to 0 \text{ in probability as }n\to\infty \text{ for fixed }j.  \end{equation}  Consider a circle packing $\widetilde\mathcal{P}^{jn}$ for $\widetilde T^{jn}$ in $\mathbb{C}$ such that the disks for $\mathfrak{v}^{n,j,0}$ and $\mathfrak{v}^{n,j,1}$ are centered at 0 and 1, respectively. Note that by our definition of $I_n'$,  $\Phi_{\rm simple}(\widetilde T^{n,j})$ can be viewed as a submap of $\Phi_{\rm simple}(\widetilde T^{jn})$, and let $\check{\mathcal{P}}^{jn}$ be the restriction of $\widetilde\mathcal{P}^{jn}$ to the disks for vertices in $\Phi_{\rm simple}(\widetilde T^{n,j})$, which can be understood as a circle embedding for  $\Phi_{\rm simple}(\widetilde T^{n,j})$. Consider a homeomorphism $f^{n,j}$ between carriers of $\widetilde\mathcal{P}^{n,j}$ and $\check{\mathcal{P}}^{jn}$ that corresponds disks  and fixes 0 and 1. Choose a deterministic sequence $j=j(n)\to\infty$ sufficiently slow, such that  $j^{1/2}\sup_{|t|\leq 2}|(jn)^{-1/2}\widetilde\mathcal{Z}^{jn}_t - Z_t|\to 0$ \text{in probability} as $n\to\infty$, and\begin{equation}\label{eq:CONE-2-new}R_{n,j}\varepsilon_{n,j} \to 0, \ \frac{|(R^{n,j})^{-1}e^{-i\theta^{n,j}} - \varphi(\eta(1/j))|}{|\varphi(\eta(1/j))|}\to 0 \text{ for $j=j(n)$ in probability as }n\to\infty. \end{equation}
    By the continuity of the curve $\eta$, as $j\to\infty$, $\varphi(\eta(1/j))\to 0$ in probability, which along with~\eqref{pf:lem:pf-pack-cone-2-N1}  further imply that for every $R>0$, with probability tending to 1 as $n\to\infty$, $B(0;R)\subseteq \mathrm{carrier}(\widetilde\mathcal{P}^{n,j})$. Therefore                                                                  
    the conditions in Theorem~\ref{thm:He-Schramm-sphere} holds for the circle embeddings $\widetilde\mathcal{P}^{n,j}$ and  $\check\mathcal{P}^{jn}$ as well as the map $f^{n,j}$. By Theorem~\ref{thm:He-Schramm-sphere}, for each $R>0$, with probability tending to 1 as $n\to\infty$,  $B(0;R)$ is within the carrier of $\check\mathcal{P}^{jn}$, $\{f^{n,j}\}$ converges uniformly to the identity in probability under the spherical metric, i.e., we may assume for each $z$ in the carrier of $\widetilde\mathcal{P}^{n,j}$, $d_{\mathrm{sp}}(f^{n,j}(z),z)\leq \widetilde\varepsilon_{n,j}$ where $\widetilde \varepsilon_{n,j}\to0 $ in probability as $n\to\infty$ for $j=j(n)$.                                        

   Now we fix $k\in\mathbb{N}$. Using the scale invariance of $\eta$ in law as in Lemma~\ref{lem:Rb}, it is not hard to argue that $\{|\eta(1/j)|^{-1}\mathrm{diam}(\eta([-k/j,k/j])):j\in\mathbb{N}\}$ is tight. Then using $\varphi(z) =\varphi'(0)z+o(|z|)$ as $z\to 0$, we have
   \begin{equation}\label{eq:CONE-3-new}\sup_{|t|\leq \frac{k}{j}}\big|\frac{\varphi(\eta(t))}{\varphi(\eta(1/j))} - \frac{ \eta(t)}{ \eta(1/j)} \big|\to 0 \ \ \text{ in probability as }j\to \infty.\end{equation}

Further gathering~\eqref{eq:CONE-1-new}, ~\eqref{eq:CONE-2-new},~\eqref{eq:CONE-3-new} and the convergence of the map $f^{n,j}$, the maximal diameter of disks for times in $[-k/j,k/j]$ tends to 0 and
   \begin{equation}\label{pf:lem:pf-pack-cone-2-N2}
       \sup_{t\in [-\frac{k}{j(n)},\frac{k}{j(n)}]}|\widetilde\mathfrak{tr}^{n\cdot j(n)}(t) -  \frac{\eta(t)}{\eta(1/j(n))}| \to 0 \ \ \ \text{in probability as } n\to\infty.
