     \end{split}
 \end{equation*}
 and the four terms on the right hand side all  converge to 0 in probability following~\eqref{eq:CONE-1-new},~\eqref{eq:CONE-2-new} and ~\eqref{eq:428-pf-a} and the closeness between $\widetilde\mathcal{P}^{n,j}$ and $\check{\mathcal{P}}^{jn}$. 


    Let   $(h^{1/j},\eta^{1/j})$ be defined by~\eqref{eq:hb-etab} for $b=1/j$, which is encoded by $\widehat Z^{j,n}:=(j^{1/2}Z_{t/j})_{t\in\mathbb{R}}$. Let $\widehat \mathcal{Z}_t^{j,n} = \widetilde\mathcal{Z}_{t/j}^{jn}$.  Then $\widehat Z^{j,n}\overset{d}{=}Z$ and $\widehat \mathcal{Z}_t^{j,n}$ is a rate $n$ continuous-time nearest-neighbor walk on $\mathbb{Z}^2$. Furthermore, 
    $$\sup_{t\in [-k,k]}|\widehat Z^{j,n}_t- n^{-1/2}\widehat \mathcal{Z}_t^{j,n}| = j^{1/2}\sup_{t\in [-k/j,k/j]}|Z_t -(nj)^{-1/2} \widetilde\mathcal{Z}_t^{jn}|,$$
