and the maximal diameter for disks for the vertices for the times in $[-k,k]$ tends to 0 in probability as $n\to\infty$. We further scale the circle packing $\widetilde\mathcal{P}^{jn}$ by $\eta^{1/j}(1)$, and this finishes the proof of Assertions ~\ref{result:thm:pack-cone-2}-\ref{result:thm:pack-cone-3} since $k$ is arbitrary and for every $j$, $\widehat Z^{j,n}\overset{d}{=} Z$ and $ \widehat \mathcal{Z}^{j,n}\overset{d}{=}\widetilde\mathcal{Z}^n$. To be more precise, we may first sample a common two-sided Brownian motion $Z$ and resample $\widetilde\mathcal{Z}^n$ according to the conditional law of $\widehat \mathcal{Z}^{j(n),n}$ given $\widehat Z^{j(n),n} = Z$. Assertion ~\ref{result:thm:pack-cone-1} and the final claim follow from~\eqref{eq:CONE-4-new}.

\label{lem:pf-pack-cone-3}
    Let $...<\widetilde t^n_{-2}<\widetilde t_{-1}^n<0$ and $0<\widetilde t_1^n<\widetilde t_2^n<...$ be the times at which $\widetilde\mathcal{Z}^n$ jumps, and $...<\widetilde s^n_{-2}<\widetilde s_{-1}^n<0$ and $0<\widetilde s_1^n<\widetilde s_2^n<...$ be the times at which $\widetilde\mathcal{L}^n$ or $\widetilde\mathcal{R}^n$ makes a downward jump. Let $\widetilde t_0^n=\widetilde s_0^n=0$. Then for every fixed $k\in\mathbb{N}$,
    $$\max\big\{\sup_{-kn\leq j\leq kn}|\widetilde t_j^n-\frac{j}{n}|,\sup_{-kn\leq j\leq kn}|\widetilde s_j^n-\frac{2j}{n}|\big\} \to 0\text{ in probability as } n\to\infty.$$

\label{def:uniftoMOT}
   Consider the setting above. We say that \emph{Riemann uniformization converges to mating of trees for $(\mathcal{Z}^n,Z^n)_{n\in\mathbb{N}}$} if the following is
true. Let $a,b\geq 0$ be deterministic such that $a+b<1$, and $I':=I_{a,b}\subseteq I$ be an interval such that the left (resp.\ right) endpoint of $I'$ has distance $a|I|$ (resp.\ $b|I|$) from the left (resp.\ right) endpoint of $I$.  Consider the SLE-decorated LQG surface encoded by $Z^n|_{I'}$ and embed it as $(\mathbb{D},h_{n,I'},\eta_{n,I'})$ such that $\eta_{n, I'}(t_{\rm mid})=0$ and $\eta_{n,I'}$ starts from 1. Let $t_{n,\rm mid}$ be as above. Consider planar map $\widehat M_{n,I'}$ encoded by $\Phi_\mathrm{M}(\mathcal{Z}^n|_{I'})$ and the trace $\widehat\mathfrak{tr}_{n,I'}$ as above  and $\mathfrak{M} (\widehat M_{n,I'})$ be the Riemann surface associated with $\widehat M_{n,I'}$. Then with probability tending to 1 as $n\to\infty$, $\widehat M_{n,I'}$ is not empty, and for the conformal map $\varphi_{n,I'}:\mathfrak{M}( \widehat M_{n,I'})\to \mathbb{D}$ sending the vertex $\mathfrak{v}_{I'}^{\mathrm{mid},n}$ to 0 and the   vertex $\check\mathfrak{tr}_{n,I'}(\widehat t^{n,\min})$ on $\widehat M_{n,I'}$  to 1,  the following holds:
\begin{enumerate} 
\item $|t_{n,\rm mid}-t_{\rm mid}|\to 0$ as $n\to\infty$ in probability; \label{cond:def:uniftoMOT-(i)}
    \item the maximal diameter of   faces of $ \mathfrak{M}(\widehat M_{n,I'})$ under the map $\varphi_{n,I'}$ tends to 0 in probability; \label{cond:def:uniftoMOT-(ii)}
    \item we have  $$\sup_{t\in I'}|\eta_{n, I'}(t)-\widehat\mathfrak{tr}_{n,I'}(t)| \to 0 \text{ in probability as } n\to\infty;$$ \label{cond:def:uniftoMOT-(iii)}
    \item                                                                                                                                                                                                                          
    we have $|\widehat t_{I'}^{n,\max}-\widehat t_{I'}^{n,\min}|\to |I'|$ as $n\to\infty$ in probability;                                                                                                                                                                                                                                                                                                     
    \label{cond:def:uniftoMOT-(v)}
    \item let $\nu_{n,I',\mathrm{L}}$ be a measure on $\partial\mathbb{D}$ that assigns $\nu(n)$ to the image of each edge   of $\mathfrak{M} (\widehat M_{n,I'})$ which is also on the left boundary of $T_{n,I'}$ where $\nu(n)>0$ is some constant. Then the Prokhorov distance between $\nu_{n,I',\mathrm{L}}$ and  $\nu_{h_{n, I'},\mathrm{L}}$, which is the restriction of the LQG boundary length measure $\nu_{h_{n, I'},\mathrm{L}}$ to the left boundary of $\eta_{n, I'}$,  tends to 0 in probability as $n\to\infty$. \label{cond:def:uniftoMOT-(iv)}
\end{enumerate}

\label{prop:cZ^n-unif-E}
    Let $\mathcal{Z}^n = (\mathcal{L}^n,\mathcal{R}^n)$ be defined as in Lemma~\ref{lem:def-cZ^n}.                                                      

    Under  $\mathbb{P}_\mathrm{E}$, $\|(2^{-n/2}\mathcal{Z}^n-Z)|_{I(0)}\|_\infty$ converges to 0 in probability, and Riemann uniformization converges to mating of trees for  $(\mathcal{Z}^n|_{I(0)},Z|_{I(0)})$ with $\nu(n)=2^{-n/2}$ in Condition~\ref{cond:def:uniftoMOT-(iv)}. Furthermore, for each compact set $K\subseteq \{(a,b):a,b\geq0,a+b<1\}$ and $\varepsilon>0$, we have 
    \begin{equation}\label{eq:q-q-prop:cZ^n-unif-E}
        \sup_{(a,b)\in K}\mathbb{P}_\mathrm{E}\big[\mathrm{err}(\mathcal{Z}^n|_{I(0)},Z|_{I(0)},a,b)\geq\varepsilon \big] \to 0 \text{ as } n\to\infty.
    \end{equation}

\label{lem:disk-unif-pf-0}
      There is a coupling of $(Z,\widetilde\mathcal{Z}^1,\widetilde\mathcal{Z}^2,...)$ such that
    \begin{enumerate}[(i)]
    \item claims $(\ref{cond:lem:disk-pf-0-(i)}),(\ref{cond:lem:disk-pf-0-(ii)}),(\ref{cond:lem:disk-pf-0-(v)})$ and $(\ref{cond:lem:disk-pf-0-(vi)})$ in Lemma~\ref{lem:disk-pf-0} hold;\label{cond:lem:disk-unif-pf-0-(i)}
        \item  {the total variation distance between the law of  the map $\widetilde M^{\mathrm{disk},n}$ and the trace $\widetilde\mathfrak{tr}^{\mathrm{disk},n}$ encoded by $\widetilde\mathcal{Z}^n$ via $\Phi_\mathrm{M}^\mathrm{disk}$ and $\Phi_\mathrm{T}^\mathrm{disk}$  and the  law of  $(M^{\mathrm{disk},n},\mathfrak{tr}^{\mathrm{disk},n})$ in Theorem~\ref{thm:unif-disk} for $\ell=\left\lceil \sqrt n \right\rceil$ tends to 0 as $n\to\infty$ up to a reparameterization of the trace $\widetilde\mathfrak{tr}^{\mathrm{disk},n}$};  \label{cond:lem:disk-unif-pf-0-(ii)}
        \item  {for each $\varepsilon\in(0,1/4)$,} Riemann uniformization converges to mating of trees for  {$(\widetilde\mathcal{Z}^n|_{[A\varepsilon,A(1-\varepsilon)]},Z|_{[A\varepsilon,A(1-\varepsilon)]})_{n\in\mathbb{N}}$}  with $\nu(n)=n^{-1/2}$ in Condition~\ref{cond:def:uniftoMOT-(iv)};   \label{cond:lem:disk-unif-pf-0-(iii)}
        \item let $B^n_\mathrm{L} = \{t\in [0,A]: \widetilde\mathcal{L}_t^n-\lim_{u\uparrow t}\widetilde\mathcal{L}_u^n \neq 0 \}$ and  $B^n_\mathrm{R} = \{t\in [0,A]: \widetilde\mathcal{R}_t^n-\lim_{u\uparrow t}\widetilde\mathcal{R}_u^n \neq 0 \}$ denote the set of times at which $\widetilde\mathcal{L}^n$ or $\widetilde\mathcal{R}^n$  jumps, respectively. Conditioned on $A$ and $\#B_\mathrm{L}^n$, the elements of $B_\mathrm{L}^n$ have the law of $\#B_\mathrm{L}^n$ uniform and independent times in $[0,A]$, and the same holds for $B_\mathrm{R}^n$ in place of $B_\mathrm{L}^n$.   \label{cond:lem:disk-unif-pf-0-(iv)}
    \end{enumerate}

\label{lem:disk-unif-pf-1}
    Consider the setting of Lemma~\ref{lem:disk-unif-pf-0}, and let $\mathfrak{v}^{\mathrm{mid},n}$ be the vertex on $\widetilde M^{\mathrm{disk},n}$ for the first downward jump time after $A/2$ of the walk $\widetilde\mathcal{Z}^n$ in the left coordinate. Let $\mathfrak{M}(\widetilde M^{\mathrm{disk},n})$ be the Riemann surface associated with $\widetilde M^{\mathrm{disk},n}$. Let $\widetilde\varphi^{\mathrm{disk},n}:\mathfrak{M}(\widetilde M^{\mathrm{disk},n})\to\mathbb{D}$ be  a conformal map that sends $\mathfrak{v}^{\mathrm{mid},n}$ to 0.  Then we have the following:
    \begin{enumerate}[(i)]
        \item The maximal diameter of faces under the map $\widetilde\varphi^{\mathrm{disk},n}$ tends to 0 in probability as $n\to\infty$;
        \item Let $\widetilde\mathfrak{tr}^{\mathrm{disk},n}:[0,A]\to\overline\mathbb{D}$ be the path on faces of $\widetilde T^{\mathrm{disk},n}$ under the embedding $\widetilde\varphi^{\mathrm{disk},n}(\mathfrak{M}(\widetilde M^{\mathrm{disk},n}))$. Then up to a rotation,
        \begin{equation}\label{eq:lem:disk-unif-pf-2}\sup_{t\in [0,A]} |\eta^\mathrm{disk}(t)-\widetilde\mathfrak{tr}^{\mathrm{disk},n}(t)|\to 0 \ \ \ \text{in probability as } n\to\infty. \end{equation}
        \item  Let $\widetilde\nu^{\mathrm{disk},n}$ be the measure on $\partial\mathbb{D}$ that assigns mass $n^{-1/2}$ to each   edge  $\widetilde\varphi^{\mathrm{disk},n}(e)$ where $e\in \mathfrak{M}(\widetilde M^{\mathrm{disk},n})$ is on the boundary. The Prohokov distance between $\widetilde\nu^{\mathrm{disk},n}$ and $\nu_{h^\mathrm{disk}}$ tends to 0 in probability as $n\to\infty$.
    \end{enumerate}

\label{lem:sph-unif-pf-2}

Consider the setting of Lemma~\ref{lem:sph-unif-pf-1}, and let $\widetilde M^{\mathrm{sp},n}$ be the planar map encoded by $\widetilde\mathcal{Z}^n$ via the map $\Phi_\mathrm{M}^\mathrm{sp}$. Let $B^{n,-}_\mathrm{L}$ be the set of times when $\widetilde\mathcal{L}^n$ makes a downward jump. Let $\mathfrak{v}^{0,n} = \mathfrak{v}^n_{t^{0,n} }$, $\mathfrak{v}^{\mathrm{mid},n} = \mathfrak{v}^n_{t^{\mathrm{mid},n} }$ and     $\mathfrak{v}^{1/4,n} = \mathfrak{v}^n_{t^{1/4,n} }$, where $t^{0,n} = \inf B^{n,-}_\mathrm{L}$, $t^{\mathrm{mid},n}  = \inf\{s\geq 1/2:s\in   B^{n,-}_\mathrm{L}\}$ and $t^{1/4,n}  = \inf\{s\geq 1/4:s\in   B^{n,-}_\mathrm{L}\}$,  also viewed  as points on $\mathfrak{M}(\widetilde M^{\mathrm{sp},n})$.
Let $\widetilde\varphi^{\mathrm{sp},n}:\mathfrak{M}(\widetilde M^{\mathrm{sp},n})\to\widehat\mathbb{C}$ be the conformal map sending $\mathfrak{v}^{0,n}$, $\mathfrak{v}^{\mathrm{mid},n}$ and $\mathfrak{v}^{1/4,n}$ to $\infty,0,1$, respectively, and we view $\widetilde\mathfrak{tr}^{\mathrm{sp},n}:[0,1]\to \widehat\mathbb{C}$ as the path on the embedded map $\widetilde M^{\mathrm{sp},n}$ via the embedding $\widetilde\varphi^{\mathrm{sp},n}(\mathfrak{M}(\widetilde M^{\mathrm{sp},n}))$. Then with probability tending to 1 as $n\to\infty$, $\mathfrak{M}(\widetilde M^{\mathrm{sp},n})$ and $\widetilde\mathfrak{tr}^{\mathrm{sp},n}$ are well-defined, and we have the following:
 \begin{enumerate}[(i)]
        \item The maximal spherical diameter of faces in $\widetilde\varphi^{\mathrm{sp},n}(\mathfrak{M}(\widetilde M^{\mathrm{sp},n}))$ tends to 0 in probability as $n\to\infty$;
        \item  We have \begin{equation}\label{eq:lem:sph-unif-pf-2}\sup_{t\in [0,1]} d_{\mathrm{sp}}(\widetilde\eta^\mathrm{sp}(t),\widetilde\mathfrak{tr}^{\mathrm{sp},n}(t))\to 0 \ \ \ \text{in probability as } n\to\infty. \end{equation}
    \end{enumerate}
